  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D2','BR-D2-03','Q-D2-04a returns A1, A2','Q-D2-04b served. The enquiry relation exists only once a surfacing exists',3);
  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D2','BR-D2-04','Q-D2-05a returns A2','Q-D2-05b served. The causal items differ only where the account did not correspond',4);
  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D2','BR-D2-05','Q-D2-06a returns A1, A2','Q-D2-06b served. The support item exists only once another person was named',5);
  insert into public.t3a_d1_branch_rule(dimension_id, rule_code, rule_condition, rule_effect, rule_order) values ('D2','BR-D2-06','Q-D2-07a returns A1','Q-D2-07b served. The holder exists only once a step was named',6);
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D2-EXEC-001-CONSTRUCT', 'construct'::public.t3a_content_family, 'D2 construct', 'D2', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"situation_classes": {"SC-D2-1": {"situation": "An item with an approaching consequence that the source leaves unassigned or whose ownership the source leaves contested", "pattern_family": "IPF-D2-01"}, "SC-D2-2": {"situation": "A shortfall the participant contributed to which the source establishes is not yet known to the affected party", "pattern_family": "IPF-D2-02"}, "SC-D2-3": {"situation": "A commitment is requested which the source establishes cannot be met as stated", "pattern_family": "IPF-D2-03"}, "SC-D2-4": {"situation": "A completed failure under review where the source distributes contribution across more than one person", "pattern_family": "IPF-D2-04"}, "SC-D2-5": {"situation": "A shortfall arising from another''s work, or from an inherited state the source establishes the participant now holds", "pattern_family": "IPF-D2-05"}, "SC-D2-6": {"situation": "A matter the source establishes exceeds the participant''s authority, knowledge or resource", "pattern_family": "IPF-D2-06"}, "SC-D2-7": {"situation": "Contribution or credit for work is contested by the source", "pattern_family": "IPF-D2-07"}}, "conduct_elements": {"CE-D2-01": {"name": "Statement of holding", "supports": "The record of who said they would carry something is the primary factual trace of ownership in a workplace", "does_not_support": "Does not support any claim about willingness, initiative or character, or about whether the statement was sincere"}, "CE-D2-02": {"name": "Action on the unheld item", "supports": "An action performed before assignment is observable and is distinct from a statement about holding", "does_not_support": "Does not support a claim that the action was the right one, sufficient, or well judged"}, "CE-D2-03": {"name": "Surfacing to the affected party", "supports": "Whether the affected party was told, and what they were told, is a fact of the record", "does_not_support": "Does not support any claim about candour, transparency or courage, and does not support a judgment of whether the disclosure was adequate"}, "CE-D2-04": {"name": "Timing of surfacing", "supports": "Sequence is recoverable from the record and is the least interpretive fact available", "does_not_support": "Does not support any claim about why the timing was as it was, and never supports \"delayed\", \"late\" or \"waited\" as a characterization"}, "CE-D2-05": {"name": "Correspondence of the causal account", "supports": "The comparison is between two records, not between a statement and what the participant privately knew", "does_not_support": "Does not support a claim of dishonesty, and does not support a claim that the participant understood the cause"}, "CE-D2-06": {"name": "Attribution of contribution", "supports": "Sources pre-designate which attributions the record supports; the mentor selects a matching item and never judges", "does_not_support": "Does not support any claim about blame, fairness or team conduct, and never supports a statement about the third party"}, "CE-D2-07": {"name": "Remedial step and its holder", "supports": "Naming a step and naming who carries it are distinguishable and both are observable", "does_not_support": "Does not support a claim that the remedy was appropriate, feasible or sufficient"}, "CE-D2-08": {"name": "Forward commitment", "supports": "A commitment and a constraint are both established by the source before observation", "does_not_support": "Does not support a prediction that the commitment would be met, or a judgment that it was realistic"}, "CE-D2-09": {"name": "Conduct when the earlier knowledge was put to the participant", "supports": "The test point is authored into the source, so the opportunity is identical for every participant", "does_not_support": "Does not support a claim about composure, defensiveness or honesty"}}, "coverage": {"CE-D2-01": ["Carried", "Carried", "Carried", "Carried"], "CE-D2-02": ["Carried", "Carried", "Carried", "Carried"], "CE-D2-03": ["Carried", "Carried", "Carried", "Carried"], "CE-D2-04": ["Carried", "Carried", "Carried", "Carried"], "CE-D2-05": ["Carried", "Carried", "Carried", "Carried"], "CE-D2-06": ["Carried", "Carried", "Carried", "Carried"], "CE-D2-07": ["Carried", "Carried", "Carried", "Carried"], "CE-D2-08": ["Carried", "Carried", "NOT IN LAUNCH DESIGN", "Carried"], "CE-D2-09": ["Carried", "Carried", "NOT IN LAUNCH DESIGN", "Carried"]}, "source_fields": {"permitted_administration_variance": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The administration variance the source permits, recorded wherever it occurs"}, "unsupported_inferences": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The inferences the source must never support"}, "compatibility_class": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The delivery form class of the source, derived from its Stage"}, "item_ownership_state": {"type": "text", "stages": "1, 2, 3, 4", "holds": "unassigned, contested or held_by_participant, as the source establishes it before observation, with any qualification"}, "knowledge_point": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The point at which the source establishes the participant knew of the shortfall, and the text that establishes it"}, "impact_point": {"type": "text", "stages": "1, 2, 3, 4", "holds": "The point at which the source establishes the consequence falls"}, "enquiry_point": {"type": "point: Enquiry point", "stages": "1, 2, 4", "holds": "The reveal or beat at which someone asks about the matter, or None"}, "enquiry_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "How the enquiry arises where it is not a reveal or beat code, and the Stage 3 enquiry event, or None"}, "knowledge_test_point": {"type": "point: Account test", "stages": "1, 2, 4", "holds": "The reveal or beat at which the established knowledge point is put to the participant"}, "affected_party": {"type": "label", "stages": "1, 2, 3, 4", "holds": "The role label of the party the source establishes as affected"}, "affected_party_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Any further affected party the source establishes, or None"}, "available_actions": {"type": "list: ACT", "stages": "2, 3, 4", "holds": "Actions performable and observable in the session, or evidenced in the Stage 3 submission; planning content is never listed"}, "material_disclosure_items": {"type": "list: MD, mapped", "stages": "1, 2, 3, 4", "holds": "Items a statement to the affected party could contain, designated before observation"}, "causal_record_set": {"type": "list: CR, mapped", "stages": "1, 2, 3, 4", "holds": "The source''s own record of what caused the shortfall, itemized"}, "attribution_support_set": {"type": "list: AS, mapped", "stages": "1, 2, 3, 4", "holds": "Attributions the source record supports; a character statement is never an item"}, "accountable_actor_set": {"type": "list: AA", "stages": "1, 2, 3, 4", "holds": "Role labels the source establishes as able to carry a remedial step, other than the participant"}, "constraint_set": {"type": "list: CS, mapped", "stages": "1, 2, 3, 4", "holds": "The constraints the source states on a forward commitment, each in its exact source text"}, "list_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "Why a list is empty, and any item withheld from a list as a character statement or planning content, or None"}, "source_note": {"type": "text", "stages": "1, 2, 3, 4", "holds": "A higher review standard or situation context the source carries, or None"}, "situation_class_label": {"type": "text", "stages": "1, 2, 3, 4", "holds": "One approved generic phrase naming the kind of situation, its time sensitivity or consequence and the information available; never the source title or scenario detail"}, "observation_mode_label": {"type": "enum: written_response, structured_live_session, work_sample, group_session", "stages": "1, 2, 3, 4", "holds": "The observation mode of the Stage at which the source is served"}}, "source": "T3A-D2-EXEC-001 v2.1"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D2-EXEC-001-CONSTRUCT' and family = 'construct'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D2-EXEC-001-DETERMINATION', 'determination_question_set'::public.t3a_content_family, 'D2 determination set', 'D2', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"questions": {"Q-D2-01": {"element": "CE-D2-01", "capture_set": "C1", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D2-02": {"element": "CE-D2-02", "capture_set": "C2", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D2-02b": {"element": "CE-D2-02", "capture_set": "C2b", "answer_type": "Bound selection, one or more", "source_bound_to": "available_actions", "served_when": "C2 records an action performed"}, "Q-D2-03a": {"element": "CE-D2-03", "capture_set": "C3a", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries affected_party"}, "Q-D2-03b": {"element": "CE-D2-03", "capture_set": "C3b", "answer_type": "Bound selection, one or more", "source_bound_to": "material_disclosure_items", "served_when": "C3a records a statement or a confirmation"}, "Q-D2-04a": {"element": "CE-D2-04", "capture_set": "C4a", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries knowledge_point and impact_point"}, "Q-D2-04b": {"element": "CE-D2-04", "capture_set": "C4b", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "C4a records a surfacing"}, "Q-D2-05a": {"element": "CE-D2-05", "capture_set": "C5a", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries causal_record_set"}, "Q-D2-05b": {"element": "CE-D2-05", "capture_set": "C5b", "answer_type": "Bound selection, one or more", "source_bound_to": "causal_record_set", "served_when": "C5a records an account that did not correspond"}, "Q-D2-06a": {"element": "CE-D2-06", "capture_set": "C6a", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries attribution_support_set"}, "Q-D2-06b": {"element": "CE-D2-06", "capture_set": "C6b", "answer_type": "Bound selection, exactly one", "source_bound_to": "attribution_support_set", "served_when": "C6a records an attribution to another person"}, "Q-D2-07a": {"element": "CE-D2-07", "capture_set": "C7a", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Always where the element is in play"}, "Q-D2-07b": {"element": "CE-D2-07", "capture_set": "C7b", "answer_type": "Bound selection, exactly one", "source_bound_to": "accountable_actor_set", "served_when": "C7a records a named step"}, "Q-D2-08a": {"element": "CE-D2-08", "capture_set": "C8a", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries constraint_set or requests a commitment"}, "Q-D2-09": {"element": "CE-D2-09", "capture_set": "C9", "answer_type": "Single select, fixed", "source_bound_to": "—", "served_when": "Source carries knowledge_test_point"}}, "capture_sets": {"C1": {"title": "What the participant stated about who held the item", "lines": ["Stated the item was theirs to carry.", "Stated the item was shared and named their own part.", "Stated the item was shared without naming their own part.", "Stated the item was another person''s to carry.", "Stated the item was unassigned without stating who would carry it.", "Made no statement about who held the item during the observation."], "bound": null, "type": "content", "whole_session": "Made no statement about who held the item during the observation."}, "C2": {"title": "What action on the item the participant stated or performed", "lines": ["Performed or began one or more of the actions the source makes available.", "Stated an action without performing one that the situation made available.", "Asked another person to carry the item.", "Stated that no action would be taken by them.", "Took no action and stated none during the observation."], "bound": null, "type": "content", "whole_session": "Took no action and stated none during the observation."}, "C2b": {"title": "Which of the available actions were performed", "lines": ["LISTED Performed one or more of the listed actions and no other.", "PERFORMED_UNLISTED_ACTION Performed an action outside the list and none of the listed actions.", "LISTED + PERFORMED_UNLISTED_ACTION Performed one or more of the listed actions and an action outside the list."], "bound": {"field": "available_actions", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C3a": {"title": "Whether the shortfall was stated to the affected party", "lines": ["Stated it to the affected party.", "Stated it to a person other than the affected party.", "Stated it to no one during the observation.", "The affected party raised it first and the participant confirmed it."], "bound": null, "type": "content", "whole_session": "Stated it to no one during the observation."}, "C3b": {"title": "What the statement contained", "lines": ["LISTED Selected each listed item the statement contained.", "CONTAINED_NO_LISTED_ITEM The statement contained none of the listed items."], "bound": {"field": "material_disclosure_items", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C4a": {"title": "Where the surfacing sat against the impact point", "lines": ["Surfaced it before the impact point.", "Surfaced it after the impact point.", "No surfacing occurred during the observation."], "bound": null, "type": "first-occurrence", "whole_session": "No surfacing occurred during the observation."}, "C4b": {"title": "Where the surfacing sat against the enquiry point", "lines": ["Surfaced it before any enquiry was made.", "Surfaced it after an enquiry was made."], "bound": null, "type": "first-occurrence", "whole_session": "—"}, "C5a": {"title": "Whether the account of the cause corresponded to the source record", "lines": ["Gave an account of the cause that corresponded to the source record.", "Gave an account of the cause that did not correspond to the source record.", "Gave no account of the cause during the observation."], "bound": null, "type": "content", "whole_session": "Gave no account of the cause during the observation."}, "C5b": {"title": "Which causal items the account omitted or contradicted", "lines": ["LISTED:OMITTED Selected each causal item the account omitted, and marked none contradicted.", "LISTED:CONTRADICTED Selected each causal item the account contradicted, and marked none omitted.", "LISTED:OMITTED + LISTED:CONTRADICTED Selected the causal items the account omitted and those it contradicted."], "bound": {"field": "causal_record_set", "selection": "one or more"}, "type": "content", "whole_session": "—"}, "C6a": {"title": "Whether the account attributed the shortfall to another person", "lines": ["Attributed it to another person only.", "Attributed it to another person and to themselves.", "Attributed it to themselves only.", "Attributed it to no person during the observation."], "bound": null, "type": "content", "whole_session": "Attributed it to no person during the observation."}, "C6b": {"title": "Which support item the attribution matches", "lines": ["LISTED Selected the support item the attribution matches.", "UNSUPPORTED_ATTRIBUTION The attribution matches no support item."], "bound": {"field": "attribution_support_set", "selection": "exactly one"}, "type": "content", "whole_session": "—"}, "C7a": {"title": "Whether a specific remedial step was named", "lines": ["Named a specific remedial step.", "Stated that something would be done without naming a step.", "Named no remedial step during the observation."], "bound": null, "type": "content", "whole_session": "Named no remedial step during the observation."}, "C7b": {"title": "Who the participant stated would carry the step", "lines": ["LISTED Selected the listed role the participant named as holder of the step.", "STATED_THEMSELVES Stated that they would carry the step themselves.", "NAMED_NO_HOLDER No holder of the step was named."], "bound": {"field": "accountable_actor_set", "selection": "exactly one"}, "type": "content", "whole_session": "—"}, "C8a": {"title": "Whether a forward commitment was stated", "lines": ["Stated a commitment with a specific time or condition.", "Stated a commitment without a specific time or condition.", "Stated that the requested commitment could not be met as asked.", "Stated no commitment during the observation."], "bound": null, "type": "content", "whole_session": "Stated no commitment during the observation."}, "C9": {"title": "What was stated when the knowledge point was put to the participant", "lines": ["Stated the knowledge point as the source records it.", "Stated a later point than the source records.", "Stated an earlier point than the source records.", "Stated no point during the observation.", "Stated the point and stated they had not raised it at that time."], "bound": null, "type": "content", "whole_session": "Stated no point during the observation."}}, "branch_rules": {"BR-D2-01": {"child": "Q-D2-02b", "parent": "Q-D2-02", "serving_answers": ["A1"], "note": "Which actions exist only once an action was performed"}, "BR-D2-02": {"child": "Q-D2-03b", "parent": "Q-D2-03a", "serving_answers": ["A1", "A2", "A4"], "note": "What the statement contained exists only once a statement or confirmation exists"}, "BR-D2-03": {"child": "Q-D2-04b", "parent": "Q-D2-04a", "serving_answers": ["A1", "A2"], "note": "The enquiry relation exists only once a surfacing exists"}, "BR-D2-04": {"child": "Q-D2-05b", "parent": "Q-D2-05a", "serving_answers": ["A2"], "note": "The causal items differ only where the account did not correspond"}, "BR-D2-05": {"child": "Q-D2-06b", "parent": "Q-D2-06a", "serving_answers": ["A1", "A2"], "note": "The support item exists only once another person was named"}, "BR-D2-06": {"child": "Q-D2-07b", "parent": "Q-D2-07a", "serving_answers": ["A1"], "note": "The holder exists only once a step was named"}}, "source": "T3A-D2-EXEC-001 v2.1"}'::jsonb from public.t3a_content_object where identifier = 'T3A-D2-EXEC-001-DETERMINATION' and family = 'determination_question_set'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('T3A-D2-EXEC-001-STATEMENT-LIBRARY', 'statement_library'::public.t3a_content_family, 'D2 statement library', 'D2', 'not_applicable'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_applicable'::public.t3a_operational_state, '{"comparison_operators": {"ST-D2-019": {"operator": "Coverage", "domain": "material_disclosure_items"}, "ST-D2-020": {"operator": "Coverage", "domain": "material_disclosure_items"}, "ST-D2-026": {"operator": "Correspondence", "domain": "causal_record_set"}, "ST-D2-027": {"operator": "Correspondence", "domain": "causal_record_set"}, "ST-D2-029": {"operator": "Omission", "domain": "causal_record_set"}, "ST-D2-030": {"operator": "Non contradiction", "domain": "causal_record_set"}, "ST-D2-031": {"operator": "Omission", "domain": "causal_record_set"}, "ST-D2-036": {"operator": "Correspondence", "domain": "attribution_support_set"}, "ST-D2-037": {"operator": "Correspondence", "domain": "attribution_support_set"}, "ST-D2-038": {"operator": "Correspondence", "domain": "attribution_support_set"}, "ST-D2-049": {"operator": "Correspondence", "domain": "knowledge_point"}, "ST-D2-050": {"operator": "Correspondence", "domain": "knowledge_point"}, "ST-D2-051": {"operator": "Correspondence", "domain": "knowledge_point"}, "ST-D2-053": {"operator": "Correspondence", "domain": "knowledge_point"}, "ST-D2-054": {"operator": "Coverage", "domain": "material_disclosure_items"}, "ST-D2-055": {"operator": "Coverage", "domain": "material_disclosure_items"}, "ST-D2-056": {"operator": "Omission", "domain": "causal_record_set"}, "ST-D2-057": {"operator": "Non contradiction", "domain": "causal_record_set"}, "ST-D2-058": {"operator": "Omission", "domain": "causal_record_set"}, "ST-D2-059": {"operator": "Correspondence", "domain": "attribution_support_set"}, "ST-D2-060": {"operator": "Correspondence", "domain": "attribution_support_set"}, "ST-D2-061": {"operator": "Correspondence", "domain": "attribution_support_set"}}, "placeholder_grammar": {"performed_listed_action_count": {"kind": "count", "bound_to": "Q-D2-02b LISTED", "grammar": "whole number from 1 to the number of items in available_actions"}, "contained_item_count": {"kind": "count", "bound_to": "Q-D2-03b LISTED", "grammar": "whole number from 1 to the number of items in material_disclosure_items"}, "omitted_causal_item_count": {"kind": "count", "bound_to": "Q-D2-05b LISTED:OMITTED", "grammar": "whole number from 1 to the number of items in causal_record_set"}, "contradicted_causal_item_count": {"kind": "count", "bound_to": "Q-D2-05b LISTED:CONTRADICTED", "grammar": "whole number from 1 to the number of items in causal_record_set"}, "affected_party_label": {"kind": "label", "bound_to": "affected_party", "grammar": "the value of affected_party on the served source"}}, "recurrence_keys": {"REK-D2-001": {"element": "CE-D2-01", "proposition": "A statement was made about who held the item", "material_variable": "Which of the six holding states was stated", "contextual_variable": "The item itself; the role labels"}, "REK-D2-002": {"element": "CE-D2-02", "proposition": "An action on the item was or was not performed before assignment", "material_variable": "Whether an action was performed", "contextual_variable": "Which action; the domain"}, "REK-D2-003": {"element": "CE-D2-03", "proposition": "The shortfall was or was not stated to the affected party", "material_variable": "Whether the affected party was told", "contextual_variable": "Who the affected party is; the channel"}, "REK-D2-004": {"element": "CE-D2-04", "proposition": "The surfacing sat before or after the impact point", "material_variable": "Which side of the impact point", "contextual_variable": "The elapsed interval; the calendar"}, "REK-D2-005": {"element": "CE-D2-05", "proposition": "The causal account did or did not correspond to the source record", "material_variable": "Whether it corresponded", "contextual_variable": "Which causal items differed"}, "REK-D2-006": {"element": "CE-D2-06", "proposition": "The shortfall was or was not attributed to another person", "material_variable": "Whether another person was named", "contextual_variable": "Which person; which support item"}, "REK-D2-007": {"element": "CE-D2-07", "proposition": "A specific remedial step was or was not named", "material_variable": "Whether a specific step was named", "contextual_variable": "Which step; which holder"}, "REK-D2-008": {"element": "CE-D2-08", "proposition": "A forward commitment was or was not stated with a specific time or condition", "material_variable": "Whether a specific time or condition was stated", "contextual_variable": "The date; the constraint"}, "REK-D2-009": {"element": "CE-D2-09", "proposition": "The stated knowledge point did or did not match the source record", "material_variable": "Whether it matched", "contextual_variable": "How far it differed"}}, "resolution_rules": {"RR-D2-01": {"pattern": "STAGE=1 + Q-D2-02=A1", "outcome": "REFUSE", "reason": "A written Stage 1 response cannot evidence an action performed"}, "RR-D2-02": {"pattern": "Q-D2-02=A1 + Q-D2-02b=UNANSWERED", "outcome": "REFUSE", "reason": "The parent records an action and the child identifies none; the service must not choose"}, "RR-D2-03": {"pattern": "Q-D2-03a=A1 + Q-D2-03b=UNANSWERED", "outcome": "REFUSE", "reason": "A statement is recorded and its content is not"}, "RR-D2-04": {"pattern": "Q-D2-03a=A2 + Q-D2-03b=UNANSWERED", "outcome": "REFUSE", "reason": "A statement is recorded and its content is not"}, "RR-D2-05": {"pattern": "Q-D2-03a=A4 + Q-D2-03b=UNANSWERED", "outcome": "REFUSE", "reason": "A confirmation is recorded and its content is not"}, "RR-D2-06": {"pattern": "Q-D2-04a=A1 + Q-D2-04b=UNANSWERED", "outcome": "REFUSE", "reason": "A surfacing is recorded and its enquiry relation is not"}, "RR-D2-07": {"pattern": "Q-D2-04a=A2 + Q-D2-04b=UNANSWERED", "outcome": "REFUSE", "reason": "A surfacing is recorded and its enquiry relation is not"}, "RR-D2-08": {"pattern": "Q-D2-05a=A2 + Q-D2-05b=UNANSWERED", "outcome": "REFUSE", "r