  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S1-001', 'source'::public.t3a_content_family, 'THE UNCLAIMED REPORT', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE UNCLAIMED REPORT", "source_digest": "e388cc5c1e51c326a605b9d0b77ddc63c9cbdcbd77c88f5f7b19ef7891c249d2", "situation": "You are a marketing coordinator on a delivery team.\n\nOn Monday morning your supervisor sent a group message to you and two colleagues — the analytics colleague and the content colleague: \"The client organization needs an updated campaign performance report by Thursday at noon. Can one of you take the lead on pulling it together?\"\n\nIt is now Wednesday at 2:00 PM. No one has replied to the message. No one has started the report.\n\nYou assumed the analytics colleague would take it, because they prepared the last one.\n\nThere are fewer than twenty-two hours until the deadline. A report of this kind usually takes six to eight hours.", "reveals": [{"code": "R1", "text": "What do you do right now?", "role": "Opening"}, {"code": "R2", "text": "Write the message you send to the group — your supervisor, the analytics colleague and the content colleague — right now.", "role": "Information"}, {"code": "R3", "text": "The report is delivered on time. On Friday your supervisor asks: \"What happened with the campaign report — why did it almost fall through?\" What do you say?", "role": "Enquiry point"}, {"code": "R4", "text": "Your supervisor adds: \"Just so I have the sequence — when did you first see that nobody had replied to Monday''s message?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "item_ownership_state is unassigned; R2 and R3 both create the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "R2 asks what is done"}, {"question": "Q-D2-02b", "state": "NOT SERVED", "basis": "BR-D2-10"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "affected_party is an addressee of the R3 message"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "knowledge_point and impact_point established"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point is R4, so both values reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty; R4 invites an account"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty; R4 creates the attribution opportunity"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "R2 and R4 both invite a remedial step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "constraint_set non-empty; R3 invites a forward statement"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at R5"}], "material_map": [{"Item": "MD1", "Item text": "that nobody has replied to the Monday message", "Where the participant meets it": "Reveal R4", "Quoted text": "nobody had replied to Monday''s message?\""}, {"Item": "MD2", "Item text": "that nobody has started the report", "Where the participant meets it": "The situation", "Quoted text": "has started the report"}, {"Item": "MD3", "Item text": "that the work usually takes six to eight hours against fewer than twenty-two remaining", "Where the participant meets it": "The situation", "Quoted text": "usually takes six to eight hours"}, {"Item": "CR1", "Item text": "the task was addressed to three people and to no individual", "Where the participant meets it": "The situation", "Quoted text": "sent a group message to you and two colleagues"}, {"Item": "CR2", "Item text": "no one replied between Monday and Wednesday", "Where the participant meets it": "Reveal R4", "Quoted text": "replied to Monday''s message?\""}, {"Item": "CR3", "Item text": "the participant assumed the analytics colleague would take it", "Where the participant meets it": "The situation", "Quoted text": "assumed the analytics colleague would take"}, {"Item": "AS1", "Item text": "the message named no individual owner", "Where the participant meets it": "The situation", "Quoted text": "Can one of you take the lead on pulling it together?"}, {"Item": "AS2", "Item text": "no colleague replied to the message", "Where the participant meets it": "The situation", "Quoted text": "replied to the message"}, {"Item": "CS1", "Item text": "\"by Thursday at noon\"", "Where the participant meets it": "The situation", "Quoted text": "by Thursday at noon"}, {"Item": "CS2", "Item text": "\"usually takes six to eight hours\"", "Where the participant meets it": "The situation", "Quoted text": "usually takes six to eight hours"}], "source_sheet": {"d2_situation_class": "SC-D2-1", "workplace_demand": "Carrying a task assigned to a group but to no individual.", "relevant_conduct": "Statements about who held the report; what was stated as done; whether the supervisor was told and what was told; the account of the two-day silence; whether colleagues were named; what was proposed and by whom; the answer at R4.", "irrelevant_conduct": "The quality of the report; tone or urgency of the message; opinions about group messaging as a practice.", "stated_standard": "\"the client organization needs an updated campaign performance report by Thursday at noon.\" Exact participant-facing text at the situation. NOTHING IN THE SOURCE STATES THAT AN UNCLAIMED GROUP TASK MUST BE CLAIMED, and no such standard may be assumed.", "stated_standard_source_quote_or_location": "\"the client organization needs an updated campaign performance report by Thursday at noon\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed. Screen-reader and extended-time accommodations permitted and recorded.", "unsupported_inferences": "That the participant was responsible for the report; that the colleagues failed; that the participant''s two days of silence caused the risk; anything about initiative or willingness.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "item_ownership_state": "Unassigned.", "knowledge_point": "Monday morning, the situation: \"your supervisor sent a group message\".", "impact_point": "Thursday at noon, the situation.", "enquiry_point": "R3", "enquiry_note": "Friday, R3: the supervisor''s debrief question.", "knowledge_test_point": "R4", "affected_party": "the supervisor", "affected_party_note": null, "material_disclosure_items": [{"id": "MD1", "text": "that nobody has replied to the Monday message"}, {"id": "MD2", "text": "that nobody has started the report"}, {"id": "MD3", "text": "that the work usually takes six to eight hours against fewer than twenty-two remaining"}], "causal_record_set": [{"id": "CR1", "text": "the task was addressed to three people and to no individual"}, {"id": "CR2", "text": "no one replied between Monday and Wednesday"}, {"id": "CR3", "text": "the participant assumed the analytics colleague would take it"}], "attribution_support_set": [{"id": "AS1", "text": "the message named no individual owner"}, {"id": "AS2", "text": "no colleague replied to the message"}], "accountable_actor_set": [{"id": "AA1", "text": "the analytics colleague"}, {"id": "AA2", "text": "the content colleague"}, {"id": "AA3", "text": "the supervisor"}], "constraint_set": [{"id": "CS1", "text": "\"by Thursday at noon\""}, {"id": "CS2", "text": "\"usually takes six to eight hours\""}], "list_note": "Exact text at R1.", "source_note": null, "situation_class_label": "An unassigned or contested work item with a deadline approaching, and a record of who was asked", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D2-S1-001", "stage_code": "S1", "source_version_hash": "e388cc5c1e51c326a605b9d0b77ddc63c9cbdcbd77c88f5f7b19ef7891c249d2", "serving_eligible": false, "verbatim": "You are a marketing coordinator on a delivery team.\n\nOn Monday morning your supervisor sent a group message to you and two colleagues — the analytics colleague and the content colleague: \"The client organization needs an updated campaign performance report by Thursday at noon. Can one of you take the lead on pulling it together?\"\n\nIt is now Wednesday at 2:00 PM. No one has replied to the message. No one has started the report.\n\nYou assumed the analytics colleague would take it, because they prepared the last one.\n\nThere are fewer than twenty-two hours until the deadline. A report of this kind usually takes six to eight hours."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S1-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S1-002', 'source'::public.t3a_content_family, 'THE SUMMARY NOT YET ASKED FOR', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE SUMMARY NOT YET ASKED FOR", "source_digest": "93948d8ec4dff34ffee56e79fc1d66eb2dc7c23590753b23f7f9b58cbd4740fa", "situation": "You are a data analyst.\n\nLast Thursday you were due to deliver a quarterly analytics summary to three people: your supervisor, the marketing lead and the client services lead.\n\nYou missed the deadline. You underestimated the data cleaning, and a technical fault in the reporting tool took a full day to resolve.\n\nThe summary is now about eighty per cent complete. You could finish it by tomorrow.\n\nIt is Tuesday morning. No one has asked about it. Your supervisor has been in meetings since Friday, the marketing lead is traveling, and the client services lead has said nothing.\n\nYou open your inbox. There are no messages about the summary.", "reveals": [{"code": "R1", "text": "What do you do this morning?", "role": "Opening"}, {"code": "R2", "text": "Write the message you send to your supervisor, the marketing lead and the client services lead about the missed deadline.", "role": "Information"}, {"code": "R3", "text": "Your supervisor replies: \"Thanks for letting me know. What went wrong with the timeline, and how will you handle it next time?\" Write your response.", "role": "Information"}, {"code": "R4", "text": "Your supervisor adds: \"One more thing for the sequence — when did you first know the summary was not going to make Thursday?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The summary is the participant''s; R2 creates the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "R2 asks what is done"}, {"question": "Q-D2-02b", "state": "NOT SERVED", "basis": "BR-D2-10"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "Three affected parties, addressed at R3"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point is established and precedes the observation"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty; R4 asks what went wrong"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty — the tool fault is an available non-self attribution"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "R4 asks how it will be handled next time"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "constraint_set non-empty; R3 invites a date"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at R5"}], "material_map": [{"Item": "MD1", "Item text": "that the Thursday deadline was missed", "Where the participant meets it": "The situation", "Quoted text": "You missed the deadline"}, {"Item": "MD2", "Item text": "that the summary is about eighty per cent complete", "Where the participant meets it": "The situation", "Quoted text": "summary is now about eighty per cent complete"}, {"Item": "MD3", "Item text": "that it could be finished by tomorrow", "Where the participant meets it": "The situation", "Quoted text": "could finish it by tomorrow"}, {"Item": "MD4", "Item text": "the two causes", "Where the participant meets it": "The situation", "Quoted text": "You underestimated the data cleaning, and a technical fault in the reporting tool took a full day to resolve"}, {"Item": "CR1", "Item text": "the data cleaning was underestimated", "Where the participant meets it": "The situation", "Quoted text": "underestimated the data cleaning"}, {"Item": "CR2", "Item text": "a technical fault in the reporting tool took a full day", "Where the participant meets it": "The situation", "Quoted text": "technical fault in the reporting tool took a full day"}, {"Item": "CR3", "Item text": "the summary is eighty per cent complete", "Where the participant meets it": "The situation", "Quoted text": "summary is now about eighty per cent complete"}, {"Item": "AS1", "Item text": "a technical fault in the reporting tool took a full day to resolve", "Where the participant meets it": "The situation", "Quoted text": "technical fault in the reporting tool took a full day to resolve"}, {"Item": "CS1", "Item text": "\"You could finish it by tomorrow\"", "Where the participant meets it": "The situation", "Quoted text": "You could finish it by tomorrow"}], "source_sheet": {"d2_situation_class": "SC-D2-2", "workplace_demand": "Surfacing a missed deadline that nobody has yet noticed.", "relevant_conduct": "Whether the shortfall was stated and to whom; when; what the statement contained; the account of cause; whether the tool fault or anyone else was named; the remedial step and its holder; the new date; the answer at R4.", "irrelevant_conduct": "The analytical quality of the summary; the merits of the reporting tool; the stakeholders'' own responsiveness.", "stated_standard": "\"Last Thursday you were due to deliver a quarterly analytics summary.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"Last Thursday you were due to deliver a quarterly analytics summary\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accessibility accommodations recorded.", "unsupported_inferences": "That silence since Thursday was deliberate; that the participant hoped it would go unnoticed; that the estimate was careless.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "item_ownership_state": "Held_by_participant.", "knowledge_point": "Established at the situation by the participant''s own account of the two causes. The exact moment is what R4 tests.", "impact_point": "Last Thursday, the delivery date, the situation.", "enquiry_point": null, "enquiry_note": "None before R3. the situation states in terms that no one has asked.", "knowledge_test_point": "R4", "affected_party": "the supervisor", "affected_party_note": "The marketing lead and the client services lead.", "material_disclosure_items": [{"id": "MD1", "text": "that the Thursday deadline was missed"}, {"id": "MD2", "text": "that the summary is about eighty per cent complete"}, {"id": "MD3", "text": "that it could be finished by tomorrow"}, {"id": "MD4", "text": "the two causes"}], "causal_record_set": [{"id": "CR1", "text": "the data cleaning was underestimated"}, {"id": "CR2", "text": "a technical fault in the reporting tool took a full day"}, {"id": "CR3", "text": "the summary is eighty per cent complete"}], "attribution_support_set": [{"id": "AS1", "text": "a technical fault in the reporting tool took a full day to resolve"}], "accountable_actor_set": [{"id": "AA1", "text": "the supervisor"}], "constraint_set": [{"id": "CS1", "text": "\"You could finish it by tomorrow\""}], "list_note": "Exact text at R1.", "source_note": null, "situation_class_label": "A shortfall the person contributed to, not yet known to the affected party, with its cause on record", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D2-S1-002", "stage_code": "S1", "source_version_hash": "93948d8ec4dff34ffee56e79fc1d66eb2dc7c23590753b23f7f9b58cbd4740fa", "serving_eligible": false, "verbatim": "You are a data analyst.\n\nLast Thursday you were due to deliver a quarterly analytics summary to three people: your supervisor, the marketing lead and the client services lead.\n\nYou missed the deadline. You underestimated the data cleaning, and a technical fault in the reporting tool took a full day to resolve.\n\nThe summary is now about eighty per cent complete. You could finish it by tomorrow.\n\nIt is Tuesday morning. No one has asked about it. Your supervisor has been in meetings since Friday, the marketing lead is traveling, and the client services lead has said nothing.\n\nYou open your inbox. There are no messages about the summary."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S1-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S1-003', 'source'::public.t3a_content_family, 'THE ANALYSIS ASKED FOR BY WEDNESDAY', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE ANALYSIS ASKED FOR BY WEDNESDAY", "source_digest": "5d3f670d833cacec11656e5e4bdf8ff15104918752156e06db997ea786cbb4c0", "situation": "You are a project coordinator.\n\nOn Monday at 9:00 AM your director stops at your desk: \"I have just come out of a leadership meeting. The executive team wants a full competitive analysis by Wednesday end of day. I need you to lead it — our top five competitors, their pricing, product features, market positioning and recent press. A full deck with visuals.\"\n\nYou know the following:\n\n- A competitive analysis of that scope usually takes two to three weeks - You have two other deliverables due this week that are already committed to clients - You have not produced a competitive analysis of this depth before - You have approximately fifty-six hours", "reveals": [{"code": "R1", "text": "What do you say to the director right now?", "role": "Opening"}, {"code": "R2", "text": "The director says: \"I understand it''s tight. What can you actually get me by Wednesday?\" What do you say?", "role": "Enquiry point"}, {"code": "R3", "text": "The two client deliverables are also due this week. What happens to them, and who handles that?", "role": "Information"}, {"code": "R4", "text": "On Wednesday the director asks: \"For my own record — at what point on Monday did you know the full scope was not going to fit in fifty-six hours?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "Ownership is contested by the source; R2 creates the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "R2 and R4 both ask what is done"}, {"question": "Q-D2-02b", "state": "NOT SERVED", "basis": "BR-D2-10"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The director is present at R2 and R3"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "knowledge_point and impact_point established"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point at R3, both values reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "R3 and R4 both invite a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "accountable_actor_set non-empty"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "THIS IS THE PRIMARY ELEMENT OF THIS SOURCE. The commitment request is the situation"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at R5"}], "material_map": [{"Item": "MD1", "Item text": "that the scope usually takes two to three weeks", "Where the participant meets it": "The situation", "Quoted text": "scope usually takes two to three weeks - You have two other deliverables due this week"}, {"Item": "MD2", "Item text": "that two client deliverables are already committed this week", "Where the participant meets it": "The situation", "Quoted text": "weeks - You have two other deliverables due this week that are already committed to clients"}, {"Item": "MD3", "Item text": "that the participant has not produced one of this depth before", "Where the participant meets it": "The situation", "Quoted text": "produced a competitive analysis of this depth"}, {"Item": "CR1", "Item text": "the scope usually takes two to three weeks", "Where the participant meets it": "The situation", "Quoted text": "scope usually takes two to three weeks - You have two other deliverables due this week"}, {"Item": "CR2", "Item text": "fifty-six hours are available", "Where the participant meets it": "The situation", "Quoted text": "are already committed to clients - You have not produced a competitive analysis of this depth before - You have approximately fifty-six"}, {"Item": "CR3", "Item text": "two other deliverables are already committed", "Where the participant meets it": "The situation", "Quoted text": "other deliverables due this week that are already committed"}, {"Item": "AS1", "Item text": "the scope was set by the executive team, not by the director or the participant", "Where the participant meets it": "The situation", "Quoted text": "executive team wants a"}, {"Item": "CS1", "Item text": "\"by Wednesday end of day\"", "Where the participant meets it": "The situation", "Quoted text": "by Wednesday end of day"}, {"Item": "CS2", "Item text": "\"two to three weeks\"", "Where the participant meets it": "The situation", "Quoted text": "two to three weeks"}, {"Item": "CS3", "Item text": "\"approximately fifty-six hours\"", "Where the participant meets it": "The situation", "Quoted text": "have approximately fifty-six hours"}], "source_sheet": {"d2_situation_class": "SC-D2-3", "workplace_demand": "Responding to a commitment request that the source establishes cannot be met as stated.", "relevant_conduct": "What was stated about holding the analysis; whether the constraint was referenced; what commitment was stated and with what time or condition; what was said about the two client deliverables and who would carry them; the answer at R4.", "irrelevant_conduct": "The analytical approach proposed; whether the participant seems confident; opinions about the executive team.", "stated_standard": "\"The executive team wants a full competitive analysis by Wednesday end of day.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"The executive team wants a full competitive analysis by Wednesday end of day\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That agreeing would be compliance and declining would be courage; that the director expects a particular answer; anything about assertiveness.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "item_ownership_state": "Contested. The director has assigned it; the source establishes it cannot be delivered as scoped.", "knowledge_point": "Monday 9:00 AM, the situation: the four bullets are known to the participant at the moment of the request.", "impact_point": "Wednesday end of day, the situation.", "enquiry_point": "R2", "enquiry_note": "R2, the director''s follow-up.", "knowledge_test_point": "R4", "affected_party": "the director", "affected_party_note": null, "material_disclosure_items": [{"id": "MD1", "text": "that the scope usually takes two to three weeks"}, {"id": "MD2", "text": "that two client deliverables are already committed this week"}, {"id": "MD3", "text": "that the participant has not produced one of this depth before"}], "causal_record_set": [{"id": "CR1", "text": "the scope usually takes two to three weeks"}, {"id": "CR2", "text": "fifty-six hours are available"}, {"id": "CR3", "text": "two other deliverables are already committed"}], "attribution_support_set": [{"id": "AS1", "text": "the scope was set by the executive team, not by the director or the participant"}], "accountable_actor_set": [{"id": "AA1", "text": "the director"}, {"id": "AA2", "text": "the executive team"}], "constraint_set": [{"id": "CS1", "text": "\"by Wednesday end of day\""}, {"id": "CS2", "text": "\"two to three weeks\""}, {"id": "CS3", "text": "\"approximately fifty-six hours\""}], "list_note": null, "source_note": null, "situation_class_label": "A request for a commitment that cannot be met as asked, with the constraints stated", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1500}, "source_identifier": "SRC-D2-S1-003", "stage_code": "S1", "source_version_hash": "5d3f670d833cacec11656e5e4bdf8ff15104918752156e06db997ea786cbb4c0", "serving_eligible": false, "verbatim": "You are a project coordinator.\n\nOn Monday at 9:00 AM your director stops at your desk: \"I have just come out of a leadership meeting. The executive team wants a full competitive analysis by Wednesday end of day. I need you to lead it — our top five competitors, their pricing, product features, market positioning and recent press. A full deck with visuals.\"\n\nYou know the following:\n\n- A competitive analysis of that scope usually takes two to three weeks - You have two other deliverables due this week that are already committed to clients - You have not produced a competitive analysis of this depth before - You have approximately fifty-six hours"}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S1-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S1-004', 'source'::public.t3a_content_family, 'THE LAUNCH REVIEW', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE LAUNCH REVIEW", "source_digest": "1dd9e4f5232ef077245808892319d4b62f00d41d89c61e608bd211178ac3a59a", "situation": "You work in a project management office. Your team of four has just completed a product launch for the client organization. It did not go well.\n\n- The launch was ten days late — scheduled for the first of the month, delivered on the eleventh - Two critical features were missing from the initial release - The client organization''s chief executive sent a formal complaint to your company''s vice-president\n\nWhat the record shows:\n\n- You were responsible for the project timeline. You set milestones that did not allow for testing time. - The features colleague was responsible for the two missing features. They flagged both as at risk two weeks before launch, and the plan was not adjusted. - Your supervisor approved the original timeline without reviewing it in detail. - The client organization changed requirements twice during the project, adding scope without extending the date.\n\nYour supervisor has called a team debrief for this afternoon and asked everyone to come prepared to discuss what went wrong.", "reveals": [{"code": "R1", "text": "What do you prepare to say at the debrief?", "role": "Opening"}, {"code": "R2", "text": "At the debrief, your supervisor opens with: \"Let''s go round. What went wrong from where you sat?\" What do you say?", "role": "Enquiry point"}, {"code": "R3", "text": "What changes for the next launch, and who makes that change?", "role": "Information"}, {"code": "R4", "text": "Your supervisor asks: \"For the record — when did you first know the timeline had no testing allowance in it?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The record places the timeline with the participant"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "R2 and R4 ask what is done"}, {"question": "Q-D2-02b", "state": "NOT SERVED", "basis": "BR-D2-10"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The supervisor is present at R3"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point established and already past"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point at R3, both values reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items — THE RICHEST CE-D2-05 SOURCE IN THE STAGE 1 BANK"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set has three supported items"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "This is the source where UNSUPPORTED_ATTRIBUTION is least likely and a supported match most likely"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "R4 asks what changes"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "NOT SERVED", "basis": "constraint_set is not_applicable. No forward commitment is requested. No answer row, no missing-state code"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at R5"}], "material_map": [{"Item": "MD1", "Item text": "that the participant set the milestones", "Where the participant meets it": "The situation", "Quoted text": "set milestones that did"}, {"Item": "MD2", "Item text": "that the milestones did not allow for testing time", "Where the participant meets it": "The situation", "Quoted text": "milestones that did not allow for testing time"}, {"Item": "MD3", "Item text": "that the features were flagged at risk two weeks out and the plan was not adjusted", "Where the participant meets it": "The situation", "Quoted text": "flagged both as at risk two weeks before launch, and the plan was not adjusted"}, {"Item": "CR1", "Item text": "the milestones did not allow for testing time", "Where the participant meets it": "The situation", "Quoted text": "milestones that did not allow for testing time"}, {"Item": "CR2", "Item text": "two features were flagged at risk two weeks before launch and the plan was not adjusted", "Where the participant meets it": "The situation", "Quoted text": "flagged both as at risk two weeks before launch, and the plan was not adjusted"}, {"Item": "CR3", "Item text": "the supervisor approved the timeline without detailed review", "Where the participant meets it": "The situation", "Quoted text": "supervisor approved the original timeline without reviewing it in detail"}, {"Item": "CR4", "Item text": "the client organization added scope twice without extending the date", "Where the participant meets it": "The situation", "Quoted text": "client organization changed requirements twice during the project, adding scope without extending the date"}, {"Item": "AS1", "Item text": "the features colleague flagged the two features at risk two weeks before launch", "Where the participant meets it": "The situation", "Quoted text": "flagged both as at risk two weeks before launch"}, {"Item": "AS2", "Item text": "the supervisor approved the timeline without reviewing it in detail", "Where the participant meets it": "The situation", "Quoted text": "supervisor approved the original timeline without reviewing it in detail"}, {"Item": "AS3", "Item text": "the client organization added scope twice without extending the date", "Where the participant meets it": "The situation", "Quoted text": "client organization changed requirements twice during the project, adding scope without extending the date"}], "source_sheet": {"d2_situation_class": "SC-D2-4", "workplace_demand": "Accounting for one''s own contribution to a failure where the record distributes contribution across four parties.", "relevant_conduct": "What was stated about holding the timeline; the account of cause against the four recorded items; whether others were named and whether the naming matches the record; the remedial step and its holder; the answer at R4.", "irrelevant_conduct": "The merits of the missing features; the client organization''s complaint; how the participant feels about the supervisor''s approval.", "stated_standard": "\"scheduled for the first of the month, delivered on the eleventh.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"scheduled for the first of the month, delivered on the eleventh\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That the participant caused the slip; that naming the features colleague or the supervisor is blame-shifting; that not naming them is generosity.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "item_ownership_state": "Held_by_participant, as to the timeline only.", "knowledge_point": "When the milestones were set. R4 tests the participant''s account of it.", "impact_point": "The scheduled launch date, the first of the month.", "enquiry_point": "R2", "enquiry_note": "R2, the supervisor''s debrief question.", "knowledge_test_point": "R4", "affected_party": "the supervisor", "affected_party_note": null, "material_disclosure_items": [{"id": "MD1", "text": "that the participant set the milestones"}, {"id": "MD2", "text": "that the milestones did not allow for testing time"}, {"id": "MD3", "text": "that the features were flagged at risk two weeks out and the plan was not adjusted"}], "causal_record_set": [{"id": "CR1", "text": "the milestones did not allow for testing time"}, {"id": "CR2", "text": "two features were flagged at risk two weeks before launch and the plan was not adjusted"}, {"id": "CR3", "text": "the supervisor approved the timeline without detailed review"}, {"id": "CR4", "text": "the client organization added scope twice without extending the date"}], "attribution_support_set": [{"id": "AS1", "text": "the features colleague flagged the two features at risk two weeks before launch"}, {"id": "AS2", "text": "the supervisor approved the timeline without reviewing it in detail"}, {"id": "AS3", "text": "the client organization added scope twice without extending the date"}], "accountable_actor_set": [{"id": "AA1", "text": "the features colleague"}, {"id": "AA2", "text": "the supervisor"}, {"id": "AA3", "text": "the client organization"}], "constraint_set": [], "list_note": "Not_applicable. Reason: no forward commitment is requested by this source. Q-D2-08a is NOT SERVED.", "source_note": null, "situation_class_label": "A completed failure under review, with contribution spread across several people on record", "observation_mode_label": "written_response", "min_seconds": 480, "max_seconds": 1800}, "source_identifier": "SRC-D2-S1-004", "stage_code": "S1", "source_version_hash": "1dd9e4f5232ef077245808892319d4b62f00d41d89c61e608bd211178ac3a59a", "serving_eligible": false, "verbatim": "You work in a project management office. Your team of four has just completed a product launch for the client organization. It did not go well.\n\n- The launch was ten days late — scheduled for the first of the month, delivered on the eleventh - Two critical features were missing from the initial release - The client organization''s chief executive sent a formal complaint to your company''s vice-president\n\nWhat the record shows:\n\n- You were responsible for the project timeline. You set milestones that did not allow for testing time. - The features colleague was responsible for the two missing features. They flagged both as at risk two weeks before launch, and the plan was not adjusted. - Your supervisor approved the original timeline without reviewing it in detail. - The client organization changed requirements twice during the project, adding scope without extending the date.\n\nYour supervisor has called a team debrief for this afternoon and asked everyone to come prepared to discuss what went wrong."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S1-004' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S1-007', 'source'::public.t3a_content_family, 'THE INHERITED ACCOUNT', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE INHERITED ACCOUNT", "source_digest": "a658fc8911f8475e7601cb1345f05af5f3822e50bf26f31f27e4494dc51dc648", "situation": "You have just been assigned to take over an account. The previous project lead left the company two weeks ago.\n\nYour supervisor hands you the file: \"This is the client organization''s account. Pick it up and keep it moving.\"\n\nReviewing the file, you find:\n\n- The project is three weeks behind the timeline committed to the client organization - Two deliverables marked complete in the tracker are about sixty per cent done - The client organization has not been told about the delays - There are no notes from the last four client check-ins - The budget is fifteen per cent overspent with no explanation in the records\n\nNone of this arose while you held the account.", "reveals": [{"code": "R1", "text": "What do you do first?", "role": "Opening"}, {"code": "R2", "text": "You are calling the client organization to update them. They do not know about the delays, the incomplete deliverables or the change of lead. Write what you plan to say in the opening of that call.", "role": "Information"}, {"code": "R3", "text": "What do you say to your supervisor about the state of the file, and what do you ask for?", "role": "Information"}, {"code": "R4", "text": "Your supervisor asks: \"So I have it straight — when did you first see that the two deliverables marked complete were not complete?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "Ownership transferred at R1; R2 creates the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "R2 asks what is done first"}, {"question": "Q-D2-02b", "state": "NOT SERVED", "basis": "BR-D2-10"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "Two affected parties addressed at R3 and R4"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "material_disclosure_items has four items"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point established and already passed"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "THIS IS THE SOURCE WHERE ATTRIBUTION TO ANOTHER IS BOTH SUPPORTED AND TRUE. The record supports it, so a participant who attributes is not doing anything the record contradicts"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "The support-set item identifier is RETAINED AND NOT RENDERED"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "R2 and R4 both invite a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "A commitment opportunity exists at R3, though the source supplies no date"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at R5"}], "material_map": [{"Item": "MD1", "Item text": "that the project is three weeks behind", "Where the participant meets it": "The situation", "Quoted text": "project is three weeks behind"}, {"Item": "MD2", "Item text": "that two deliverables marked complete are about sixty per cent done", "Where the participant meets it": "The situation", "Quoted text": "deliverables marked complete in the tracker are about sixty per cent done - The client organization has not been told about the"}, {"Item": "MD3", "Item text": "that the budget is fifteen per cent overspent", "Where the participant meets it": "The situation", "Quoted text": "about the delays - There are no notes from the last four client check-ins - The budget is fifteen per cent overspent"}, {"Item": "MD4", "Item text": "that the lead has changed", "Where the participant meets it": "The situation", "Quoted text": "The previous project lead left the company two weeks ago"}, {"Item": "CR1", "Item text": "the previous lead left two weeks ago", "Where the participant meets it": "The situation", "Quoted text": "previous project lead left the company two weeks ago"}, {"Item": "CR2", "Item text": "the tracker records two deliverables as complete which are not", "Where the participant meets it": "The situation", "Quoted text": "deliverables marked complete in the tracker are about sixty per cent done - The client organization has not been told about the"}, {"Item": "CR3", "Item text": "the client organization was not informed of the delays", "Where the participant meets it": "The situation", "Quoted text": "client organization - Two deliverables marked complete in the tracker are about sixty per cent done - The client organization has not"}, {"Item": "CR4", "Item text": "there are no notes from four check-ins", "Where the participant meets it": "The situation", "Quoted text": "are about sixty per cent done - The client organization has not been told about the delays - There are no notes"}, {"Item": "AS1", "Item text": "the shortfalls arose before the participant was assigned", "Where the participant meets it": "The situation", "Quoted text": "None of this arose while you held the account"}, {"Item": "AS2", "Item text": "the tracker was inaccurate when handed over", "Where the participant meets it": "The situation", "Quoted text": "Two deliverables marked complete in the tracker are about sixty per cent done"}, {"Item": "CS1", "Item text": "\"keep it moving\"", "Where the participant meets it": "The situation", "Quoted text": "keep it moving.\" Reviewing"}], "source_sheet": {"d2_situation_class": "SC-D2-5", "workplace_demand": "Holding work whose shortfalls arose before the participant held it.", "relevant_conduct": "What was stated about who holds the account and its shortfalls; what was stated to the client organization and what it contained; what was stated to the supervisor; the account of cause; whether the previous lead was named; the remedial step and its holder; the answer at R4.", "irrelevant_conduct": "The previous project lead''s conduct or character; the quality of the tracker; opinions about the handover.", "stated_standard": "\"three weeks behind the timeline committed to the client organization.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"three weeks behind the timeline committed to the client organization\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That the participant inherited a mess through anyone''s fault; that naming the previous lead is deflection; that not naming them is loyalty.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "item_ownership_state": "Held_by_participant, from the moment of assignment only.", "knowledge_point": "On reviewing the file, the situation. R4 tests the participant''s account of it.", "impact_point": "The committed client timeline, already three weeks passed at the situation.", "enquiry_point": null, "enquiry_note": "None before R4. Nobody asks.", "knowledge_test_point": "R4", "affected_party": "the client organization", "affected_party_note": "The supervisor is a second affected party at R3.", "material_disclosure_items": [{"id": "MD1", "text": "that the project is three weeks behind"}, {"id": "MD2", "text": "that two deliverables marked complete are about sixty per cent done"}, {"id": "MD3", "text": "that the budget is fifteen per cent overspent"}, {"id": "MD4", "text": "that the lead has changed"}], "causal_record_set": [{"id": "CR1", "text": "the previous lead left two weeks ago"}, {"id": "CR2", "text": "the tracker records two deliverables as complete which are not"}, {"id": "CR3", "text": "the client organization was not informed of the delays"}, {"id": "CR4", "text": "there are no notes from four check-ins"}], "attribution_support_set": [{"id": "AS1", "text": "the shortfalls arose before the participant was assigned"}, {"id": "AS2", "text": "the tracker was inaccurate when handed over"}], "accountable_actor_set": [{"id": "AA1", "text": "the supervisor"}, {"id": "AA2", "text": "the client organization"}], "constraint_set": [{"id": "CS1", "text": "\"keep it moving\""}], "list_note": "Exact text at R1. NOTE: this is a direction, not a dated constraint, and Q-D2-08a A1 requires a specific time or condition that the source does not supply. The answer is still recorded from what the participant states.", "source_note": null, "situation_class_label": "A shortfall arising from another person''s work or an inherited state the person now holds", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D2-S1-007", "stage_code": "S1", "source_version_hash": "a658fc8911f8475e7601cb1345f05af5f3822e50bf26f31f27e4494dc51dc648", "serving_eligible": false, "verbatim": "You have just been assigned to take over an account. The previous project lead left the company two weeks ago.\n\nYour supervisor hands you the file: \"This is the client organization''s account. Pick it up and keep it moving.\"\n\nReviewing the file, you find:\n\n- The project is three weeks behind the timeline committed to the client organization - Two deliverables marked complete in the tracker are about sixty per cent done - The client organization has not been told about the delays - There are no notes from the last four client check-ins - The budget is fifteen per cent overspent with no explanation in the records\n\nNone of this arose while you held the account."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S1-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S1-008', 'source'::public.t3a_content_family, 'THE JOINT REPORT', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE JOINT REPORT", "source_digest": "942e997466e8be9ec1b738289a12796c950b9097d75392c2f38fdedd083f76ff", "situation": "You are a business analyst. You and a co-author were jointly assigned to produce a market research report for your director. It is due tomorrow at 9:00 AM.\n\nYou were responsible for Sections 1 to 3 — market size, trends and competitor overview. The co-author was responsible for Sections 4 to 6 — customer segmentation, pricing analysis and recommendations.\n\nYou completed your sections yesterday and sent them over for integration.\n\nTonight at 8:00 PM the co-author sends you the combined report. You open it:\n\n- Your Sections 1 to 3 are as you sent them - Section 4''s customer segmentation figures do not add up - Section 5 is missing the pricing comparison table the director specifically asked for - Section 6''s recommendations contradict the data in your Section 2\n\nIt is now 8:15 PM. The report is due in under thirteen hours. Both names are on it.", "reveals": [{"code": "R1", "text": "What do you do right now?", "role": "Opening"}, {"code": "R2", "text": "Write the message you send to the co-author right now.", "role": "Information"}, {"code": "R3", "text": "It is 7:30 AM. The report is due in ninety minutes. What do you send to the director, and what does it say?", "role": "Information"}, {"code": "R4", "text": "The director replies: \"Before I read it — when did you first see that Sections 4 to 6 had problems?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "item_ownership_state is contested; R2 creates the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "R2 asks what is done"}, {"question": "Q-D2-02b", "state": "NOT SERVED", "basis": "BR-D2-10"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The director is addressed at R4"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "knowledge_point 8:15 PM, impact_point 9:00 AM"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty and the attribution is supported by the record"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "NAMING THE CO-AUTHOR IS NOT RENDERED — the support-set identifier is retained only"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "R2 and R4 both invite a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "constraint_set non-empty; R4 invites a commitment"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at R5"}], "material_map": [{"Item": "MD1", "Item text": "that the segmentation figures do not add up", "Where the participant meets it": "The situation", "Quoted text": "segmentation figures do not add"}, {"Item": "MD2", "Item text": "that the requested pricing comparison table is missing", "Where the participant meets it": "The situation", "Quoted text": "missing the pricing comparison table"}, {"Item": "MD3", "Item text": "that Section 6 contradicts Section 2", "Where the participant meets it": "The situation", "Quoted text": "Sections 1 to 3 are as you sent them - Section 4''s customer segmentation figures do not add up - Section 5"}, {"Item": "MD4", "Item text": "that the defects sit in Sections 4 to 6", "Where the participant meets it": "The situation", "Quoted text": "Section 4''s customer segmentation figures do not add up"}, {"Item": "CR1", "Item text": "the participant''s sections were sent complete yesterday", "Where the participant meets it": "The situation", "Quoted text": "sections yesterday and sent"}, {"Item": "CR2", "Item text": "integration was carried out by the co-author", "Where the participant meets it": "The situation", "Quoted text": "the co-author sends you the combined report"}, {"Item": "CR3", "Item text": "the three defects are all in Sections 4 to 6", "Where the participant meets it": "The situation", "Quoted text": "Sections 1 to 3 are as you sent them - Section 4''s customer segmentation figures do not add up - Section 5"}, {"Item": "AS1", "Item text": "Sections 4 to 6 were the co-author''s responsibility", "Where the participant meets it": "The situation", "Quoted text": "The co-author was responsible for Sections 4 to 6"}, {"Item": "AS2", "Item text": "the participant''s sections were delivered as sent", "Where the participant meets it": "The situation", "Quoted text": "sections yesterday and sent"}, {"Item": "CS1", "Item text": "\"due tomorrow at 9:00 AM\"", "Where the participant meets it": "The situation", "Quoted text": "due tomorrow at 9:00 AM"}, {"Item": "CS2", "Item text": "\"under thirteen hours\"", "Where the participant meets it": "The situation", "Quoted text": "under thirteen hours. Both"}], "source_sheet": {"d2_situation_class": "SC-D2-1", "workplace_demand": "A jointly attributed deliverable whose defective portion is another''s work.", "relevant_conduct": "What was stated about who holds the report and which parts; what was stated to the director and when; what the statement contained; the account of the three defects; whether the co-author was named; the remedial step and its holder; the answer at R4.", "irrelevant_conduct": "The correct segmentation figures; the merits of the recommendations; the co-author''s competence.", "stated_standard": "\"the pricing comparison table the director specifically asked for.\" Exact text at the situation. This is the one explicit requirement the source establishes.", "stated_standard_source_quote_or_location": "\"the pricing comparison table the director specifically asked for\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That the co-author was negligent; that the participant should or should not fix another''s sections; anything about fairness of workload.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "item_ownership_state": "Contested. Both names are on the report; the defects sit in the co-author''s sections.", "knowledge_point": "8:15 PM, the situation: \"You open it\".", "impact_point": "9:00 AM tomorrow, the situation.", "enquiry_point": null, "enquiry_note": "R4, the director''s question.", "knowledge_test_point": "R4", "affected_party": "the director", "affected_party_note": null, "material_disclosure_items": [{"id": "MD1", "text": "that the segmentation figures do not add up"}, {"id": "MD2", "text": "that the requested pricing comparison table is missing"}, {"id": "MD3", "text": "that Section 6 contradicts Section 2"}, {"id": "MD4", "text": "that the defects sit in Sections 4 to 6"}], "causal_record_set": [{"id": "CR1", "text": "the participant''s sections were sent complete yesterday"}, {"id": "CR2", "text": "integration was carried out by the co-author"}, {"id": "CR3", "text": "the three defects are all in Sections 4 to 6"}], "attribution_support_set": [{"id": "AS1", "text": "Sections 4 to 6 were the co-author''s responsibility"}, {"id": "AS2", "text": "the participant''s sections were delivered as sent"}], "accountable_actor_set": [{"id": "AA1", "text": "the co-author"}, {"id": "AA2", "text": "the director"}], "constraint_set": [{"id": "CS1", "text": "\"due tomorrow at 9:00 AM\""}, {"id": "CS2", "text": "\"under thirteen hours\""}], "list_note": null, "source_note": null, "situation_class_label": "An unassigned or contested work item with a deadline approaching, and a record of who was asked", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D2-S1-008", "stage_code": "S1", "source_version_hash": "942e997466e8be9ec1b738289a12796c950b9097d75392c2f38fdedd083f76ff", "serving_eligible": false, "verbatim": "You are a business analyst. You and a co-author were jointly assigned to produce a market research report for your director. It is due tomorrow at 9:00 AM.\n\nYou were responsible for Sections 1 to 3 — market size, trends and competitor overview. The co-author was responsible for Sections 4 to 6 — customer segmentation, pricing analysis and recommendations.\n\nYou completed your sections yesterday and sent them over for integration.\n\nTonight at 8:00 PM the co-author sends you the combined report. You open it:\n\n- Your Sections 1 to 3 are as you sent them - Section 4''s customer segmentation figures do not add up - Section 5 is missing the pricing comparison table the director specifically asked for - Section 6''s recommendations contradict the data in your Section 2\n\nIt is now 8:15 PM. The report is due in under thirteen hours. Both names are on it."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S1-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S1-009', 'source'::public.t3a_content_family, 'THE PAGES BEYOND THE CONTRACT', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE PAGES BEYOND THE CONTRACT", "source_digest": "d0d4863a9dce89f55b50d3d321a126d37c53c1ff62770e60ce0cf314c1c88572", "situation": "You are a project coordinator managing a website redesign for the client organization. The scope, timeline and budget were agreed six weeks ago:\n\n- Scope: the homepage, five product pages and the contact page — seven pages - Timeline: eight weeks - Budget: thirty-five thousand dollars\n\nOver the past three weeks the client organization''s marketing lead has made further requests:\n\n- Week four: an About Us page as well. You agreed. - Week five: a blog page template. You agreed. - Week six, today: an e-commerce page for a new product.\n\nYou are now at nine pages against a seven-page contract. The e-commerce page requires new functionality. Two weeks remain. Your team is already stretched.\n\nYou have not flagged any of the additions to your supervisor, and the contract has not been changed.", "reveals": [{"code": "R1", "text": "What do you say to the client organization''s marketing lead about the e-commerce page?", "role": "Opening"}, {"code": "R2", "text": "Your supervisor asks: \"How did we get to nine pages on a seven-page contract with no scope change request?\" What do you say?", "role": "Enquiry point"}, {"code": "R3", "text": "What happens to the two remaining weeks, and who does what?", "role": "Information"}, {"code": "R4", "text": "Your supervisor adds: \"And for the sequence — at which request did you first know you were outside the contracted scope?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The participant manages the project; R2 and R3 create the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "R2 and R4 ask what is done"}, {"question": "Q-D2-02b", "state": "NOT SERVED", "basis": "BR-D2-10"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The supervisor is addressed at R3"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "knowledge_point at week four, impact_point at the timeline"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point at R3, both values reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "R4 invites a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "constraint_set non-empty; R2 and R4 both invite a commitment"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at R5"}], "material_map": [{"Item": "MD1", "Item text": "that the project is at nine pages against a seven-page contract", "Where the participant meets it": "The situation", "Quoted text": "nine pages against a seven-page contract"}, {"Item": "MD2", "Item text": "that no scope change request was raised", "Where the participant meets it": "Reveal R2", "Quoted text": "no scope change request?\""}, {"Item": "MD3", "Item text": "that the e-commerce page requires new functionality", "Where the participant meets it": "The situation", "Quoted text": "page requires new functionality"}, {"Item": "MD4", "Item text": "that two weeks remain", "Where the participant meets it": "The situation", "Quoted text": "The e-commerce page requires new functionality. Two weeks remain"}, {"Item": "CR1", "Item text": "the contract specified seven pages", "Where the participant meets it": "The situation", "Quoted text": "pages against a seven-page contract"}, {"Item": "CR2", "Item text": "three further pages were requested in weeks four, five and six", "Where the participant meets it": "The situation", "Quoted text": "six weeks ago: - Scope: the homepage, five product pages and the contact page — seven pages - Timeline: eight weeks -"}, {"Item": "CR3", "Item text": "the first two were agreed", "Where the participant meets it": "The situation", "Quoted text": "Week five: a blog page template. You agreed"}, {"Item": "CR4", "Item text": "no scope change request was raised and the contract was not changed", "Where the participant meets it": "Reveal R2", "Quoted text": "contract with no scope change request?\""}, {"Item": "AS1", "Item text": "the requests originated with the client organization''s marketing lead", "Where the participant meets it": "The situation", "Quoted text": "client organization''s marketing lead has made further requests"}, {"Item": "CS1", "Item text": "\"eight weeks\"", "Where the participant meets it": "The situation", "Quoted text": "eight weeks - Budget"}, {"Item": "CS2", "Item text": "\"thirty-five thousand dollars\"", "Where the participant meets it": "The situation", "Quoted text": "thirty-five thousand dollars Over"}, {"Item": "CS3", "Item text": "\"Two weeks remain\"", "Where the participant meets it": "The situation", "Quoted text": "Two weeks remain. Your"}], "source_sheet": {"d2_situation_class": "SC-D2-3", "workplace_demand": "A commitment repeatedly extended beyond an agreed boundary without a record.", "relevant_conduct": "What was stated about who held the scope decisions; what was said to the marketing lead; what was said to the supervisor and when; the account of the three requests; whether the marketing lead was named as cause; the remedial step and its holder; the commitment on the remaining two weeks; the answer at R4.", "irrelevant_conduct": "The merits of the additional pages; the client relationship; whether the budget was generous.", "stated_standard": "\"Scope: the homepage, five product pages and the contact page — seven pages\"; \"Budget: thirty-five thousand dollars\"; \"Timeline: eight weeks.\" Exact text at the situation. THIS SOURCE HAS THE MOST EXPLICIT STATED STANDARD IN THE STAGE 1 BANK.", "stated_standard_source_quote_or_location": "\"Scope: the homepage, five product pages and the contact page — seven pages\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That agreeing to the earlier requests was weakness; that the marketing lead was exploiting the participant; anything about the participant''s ability to say no.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "item_ownership_state": "Held_by_participant.", "knowledge_point": "Week four, the first out-of-scope request. R4 tests the participant''s account of it.", "impact_point": "The eight-week timeline, two weeks remaining at the situation.", "enquiry_point": "R2", "enquiry_note": "R2, the supervisor''s question.", "knowledge_test_point": "R4", "affected_party": "the supervisor", "affected_party_note": null, "material_disclosure_items": [{"id": "MD1", "text": "that the project is at nine pages against a seven-page contract"}, {"id": "MD2", "text": "that no scope change request was raised"}, {"id": "MD3", "text": "that the e-commerce page requires new functionality"}, {"id": "MD4", "text": "that two weeks remain"}], "causal_record_set": [{"id": "CR1", "text": "the contract specified seven pages"}, {"id": "CR2", "text": "three further pages were requested in weeks four, five and six"}, {"id": "CR3", "text": "the first two were agreed"}, {"id": "CR4", "text": "no scope change request was raised and the contract was not changed"}], "attribution_support_set": [{"id": "AS1", "text": "the requests originated with the client organization''s marketing lead"}], "accountable_actor_set": [{"id": "AA1", "text": "the supervisor"}, {"id": "AA2", "text": "the client organization''s marketing lead"}], "constraint_set": [{"id": "CS1", "text": "\"eight weeks\""}, {"id": "CS2", "text": "\"thirty-five thousand dollars\""}, {"id": "CS3", "text": "\"Two weeks remain\""}], "list_note": null, "source_note": null, "situation_class_label": "A request for a commitment that cannot be met as asked, with the constraints stated", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D2-S1-009", "stage_code": "S1", "source_version_hash": "d0d4863a9dce89f55b50d3d321a126d37c53c1ff62770e60ce0cf314c1c88572", "serving_eligible": false, "verbatim": "You are a project coordinator managing a website redesign for the client organization. The scope, timeline and budget were agreed six weeks ago:\n\n- Scope: the homepage, five product pages and the contact page — seven pages - Timeline: eight weeks - Budget: thirty-five thousand dollars\n\nOver the past three weeks the client organization''s marketing lead has made further requests:\n\n- Week four: an About Us page as well. You agreed. - Week five: a blog page template. You agreed. - Week six, today: an e-commerce page for a new product.\n\nYou are now at nine pages against a seven-page contract. The e-commerce page requires new functionality. Two weeks remain. Your team is already stretched.\n\nYou have not flagged any of the additions to your supervisor, and the contract has not been changed."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S1-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S1-010', 'source'::public.t3a_content_family, 'THE CAMPAIGN AT THE HALFWAY MARK', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 1, "title": "THE CAMPAIGN AT THE HALFWAY MARK", "source_digest": "6219b01ffb34f1781642b66a84ed0c7027f91c6084c8077af419721050e83cad", "situation": "You are a marketing specialist. Three weeks ago you launched a digital advertising campaign for the client organization. The budget was twenty-five thousand dollars and the target was two hundred qualified leads over six weeks.\n\nAt the halfway mark:\n\n- Leads so far: 38. The target for this point was 100. - Cost per lead: $658. The budget target was $125. - Click-through rate: 0.8 per cent. The industry average is 2.5 per cent. - Half the budget has been spent.\n\nWhat the record shows:\n\n- You designed the targeting and the creative direction - The audience parameters you chose are narrow, and that is the likely cause of the shortfall - Your supervisor reviews campaign performance monthly, and the next review is in one week - The client organization has not asked for an update - Adjusting the targeting now could improve the remaining three weeks materially\n\nNo one is asking you for an update.", "reveals": [{"code": "R1", "text": "What do you do this week?", "role": "Opening"}, {"code": "R2", "text": "Write the update you send to your supervisor about the campaign.", "role": "Information"}, {"code": "R3", "text": "Two days later the client organization writes: \"How is the campaign tracking against the two hundred?\" What do you say?", "role": "Enquiry point"}, {"code": "R4", "text": "Your supervisor asks: \"For the record — when did you first see the cost per lead was running above the budget target?\" What is your answer?", "role": "Account test"}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The record places the targeting decision with the participant"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "R2 asks what is done this week"}, {"question": "Q-D2-02b", "state": "NOT SERVED", "basis": "BR-D2-10"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The supervisor is addressed at R3"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "knowledge_point at the halfway mark, impact_point three weeks out"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point at R4, both values reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "The question is served because the opportunity to attribute is genuine and a substantive \"attributed to no person\" option exists. IT IS NOT CONDITIONAL ON WHETHER AN ATTRIBUTION HAPPENED — that would be selection bias"}, {"question": "Q-D2-06b", "state": "NOT SERVED", "basis": "The source designates no attribution_support_set item, so the bound question cannot be offered"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "R2 invites a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "constraint_set non-empty; R3 and R4 both invite a commitment"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at R5"}], "material_map": [{"Item": "MD1", "Item text": "that leads are at 38 against 100", "Where the participant meets it": "The situation", "Quoted text": "Leads so far: 38. The target for this point was 100"}, {"Item": "MD2", "Item text": "that cost per lead is $658 against $125", "Where the participant meets it": "The situation", "Quoted text": "Cost per lead: $658"}, {"Item": "MD3", "Item text": "that half the budget is spent", "Where the participant meets it": "The situation", "Quoted text": "Half the budget has been spent"}, {"Item": "MD4", "Item text": "that the targeting parameters are the likely cause", "Where the participant meets it": "The situation", "Quoted text": "targeting and the creative direction - The audience parameters you chose are narrow, and that is the likely cause of the shortfall"}, {"Item": "CR1", "Item text": "the participant designed the targeting and creative direction", "Where the participant meets it": "The situation", "Quoted text": "designed the targeting and the creative direction - The audience parameters you chose are narrow, and that is the likely cause of"}, {"Item": "CR2", "Item text": "the audience parameters are narrow", "Where the participant meets it": "The situation", "Quoted text": "audience parameters you chose are narrow"}, {"Item": "CR3", "Item text": "the narrow parameters are the likely cause of the shortfall", "Where the participant meets it": "The situation", "Quoted text": "parameters you chose are narrow, and that is the likely cause of the shortfall"}, {"Item": "CS1", "Item text": "\"two hundred qualified leads over six weeks\"", "Where the participant meets it": "The situation", "Quoted text": "two hundred qualified leads over six weeks"}, {"Item": "CS2", "Item text": "\"the remaining three weeks\"", "Where the participant meets it": "The situation", "Quoted text": "the remaining three weeks"}], "source_sheet": {"d2_situation_class": "SC-D2-2", "workplace_demand": "Surfacing underperformance in one''s own work before anyone asks.", "relevant_conduct": "What was stated about holding the targeting decision; whether the supervisor was told and when; what the statement contained; what was said to the client organization; the account of cause; the remedial step and its holder; the commitment on the remaining three weeks; the answer at R4.", "irrelevant_conduct": "The merits of the creative; whether the targets were realistic; industry benchmarks as such.", "stated_standard": "\"a target of two hundred qualified leads over six weeks\"; \"The budget target was $125.\" Exact text at the situation.", "stated_standard_source_quote_or_location": "\"The budget target was $125\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Reveal order fixed; accommodations recorded.", "unsupported_inferences": "That waiting for the monthly review would be concealment; that the participant knew the campaign would fail; anything about candour.", "compatibility_class": "S1-WRITTEN-SEQUENTIAL", "item_ownership_state": "Held_by_participant.", "knowledge_point": "The halfway mark, the situation, when the four figures are before the participant.", "impact_point": "The end of the six-week campaign, three weeks away.", "enquiry_point": "R3", "enquiry_note": "R3, the client organization''s question. The supervisor never asks.", "knowledge_test_point": "R4", "affected_party": "the supervisor", "affected_party_note": "The client organization is a second affected party from R3.", "material_disclosure_items": [{"id": "MD1", "text": "that leads are at 38 against 100"}, {"id": "MD2", "text": "that cost per lead is $658 against $125"}, {"id": "MD3", "text": "that half the budget is spent"}, {"id": "MD4", "text": "that the targeting parameters are the likely cause"}], "causal_record_set": [{"id": "CR1", "text": "the participant designed the targeting and creative direction"}, {"id": "CR2", "text": "the audience parameters are narrow"}, {"id": "CR3", "text": "the narrow parameters are the likely cause of the shortfall"}], "attribution_support_set": [], "accountable_actor_set": [{"id": "AA1", "text": "the supervisor"}], "constraint_set": [{"id": "CS1", "text": "\"two hundred qualified leads over six weeks\""}, {"id": "CS2", "text": "\"the remaining three weeks\""}], "list_note": "Recorded as explicit none. THE RECORD SUPPORTS NO ATTRIBUTION TO ANOTHER PERSON. Q-D2-06b therefore has no selectable support item and only UNSUPPORTED_ATTRIBUTION is reachable where an attribution is made.", "source_note": null, "situation_class_label": "A shortfall the person contributed to, not yet known to the affected party, with its cause on record", "observation_mode_label": "written_response", "min_seconds": 420, "max_seconds": 1800}, "source_identifier": "SRC-D2-S1-010", "stage_code": "S1", "source_version_hash": "6219b01ffb34f1781642b66a84ed0c7027f91c6084c8077af419721050e83cad", "serving_eligible": false, "verbatim": "You are a marketing specialist. Three weeks ago you launched a digital advertising campaign for the client organization. The budget was twenty-five thousand dollars and the target was two hundred qualified leads over six weeks.\n\nAt the halfway mark:\n\n- Leads so far: 38. The target for this point was 100. - Cost per lead: $658. The budget target was $125. - Click-through rate: 0.8 per cent. The industry average is 2.5 per cent. - Half the budget has been spent.\n\nWhat the record shows:\n\n- You designed the targeting and the creative direction - The audience parameters you chose are narrow, and that is the likely cause of the shortfall - Your supervisor reviews campaign performance monthly, and the next review is in one week - The client organization has not asked for an update - Adjusting the targeting now could improve the remaining three weeks materially\n\nNo one is asking you for an update."}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S1-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S2-001', 'source'::public.t3a_content_family, 'THE OUTAGE AND THE PAYROLL DEADLINE', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE OUTAGE AND THE PAYROLL DEADLINE", "source_digest": "f9e50af837ac3fec066f8e4e4d29c76f16a5c833c9eb7d6460f3bb5cdf12bf67", "mentor_brief": "The mentor reads the scripted lines of the human resources director. The mentor does not know what engineering has said, does not know the supervisor is unreachable, and must not offer either. The mentor must not escalate, harden, repeat or add pressure at any point, whatever the participant says. The mentor''s tone is constant across every session.", "participant_pre_brief": "You are a customer success coordinator. The client organization is having a system outage that is stopping their end-of-month payroll run.\n\nThe outage began two hours ago. Your engineering team knows and has given no estimate for resolution. You asked for one at 12:45 PM and were told they could not give one yet.\n\nYour supervisor is in a board meeting and unreachable for at least ninety minutes.\n\nThe client organization''s payroll must run by 5:00 PM or two hundred people are not paid on time. It is 1:30 PM. You do not have the technical knowledge to resolve the outage yourself.\n\nThe client organization''s human resources director is calling now.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Thanks for taking the call. I have been holding for a while. Our payroll has to go out today — two hundred people are counting on it. I will let you start.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C3a", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4a", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What is happening with the outage?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C3a", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4a", "state": "update"}, {"set": "C4b", "state": "open"}, {"set": "C5a", "state": "open"}]}, {"beat": "B4", "type": "ASK", "spoken": "I need a time. Can you tell me payroll will run by five?", "direction": "Read once, verbatim.", "capture": [{"set": "C8a", "state": "open"}]}, {"beat": "B5", "type": "ASK", "spoken": "What happens next, and who is doing it?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C7a", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have the sequence right — when did you first know engineering could not give a resolution time?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}, {"set": "C5a", "state": "update"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C6b", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Understood. Thank you.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3a", "state": "final"}, {"set": "C4a", "state": "final"}, {"set": "C5a", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C7a", "state": "final"}, {"set": "C8a", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "Ownership is contested; B2 and B3 create the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "ACT-01, ACT-02 and ACT-03 eligible; ACT-04 NOT eligible"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The affected party is on the call"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "knowledge_point 12:45 PM, impact_point 5:00 PM"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty and supported by the record"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "The support-set identifier is retained and NOT rendered"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 asks what happens next"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 requests a commitment against a stated constraint"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at B6"}], "material_map": [{"Item": "MD1", "Item text": "that engineering has given no resolution estimate", "Where the participant meets it": "The pre-brief", "Quoted text": "engineering team knows and has given no estimate for resolution"}, {"Item": "MD2", "Item text": "that the participant cannot resolve it themselves", "Where the participant meets it": "The pre-brief", "Quoted text": "You do not have the technical knowledge to resolve the outage yourself"}, {"Item": "MD3", "Item text": "that the supervisor is unreachable for at least ninety minutes", "Where the participant meets it": "The pre-brief", "Quoted text": "supervisor is in a board meeting and unreachable for at least ninety minutes"}, {"Item": "CR1", "Item text": "the outage began two hours ago", "Where the participant meets it": "The pre-brief", "Quoted text": "outage began two hours ago"}, {"Item": "CR2", "Item text": "engineering is aware and has given no estimate", "Where the participant meets it": "The pre-brief", "Quoted text": "engineering team knows and has given no estimate"}, {"Item": "CR3", "Item text": "the participant asked for an estimate at 12:45 PM", "Where the participant meets it": "The pre-brief", "Quoted text": "You asked for one at 12:45 PM"}, {"Item": "AS1", "Item text": "engineering has not provided a resolution estimate", "Where the participant meets it": "The pre-brief", "Quoted text": "engineering team knows and has given no estimate for resolution"}, {"Item": "CS1", "Item text": "\"by 5:00 PM\"", "Where the participant meets it": "The pre-brief", "Quoted text": "by 5:00 PM or"}, {"Item": "CS2", "Item text": "\"unreachable for at least ninety minutes\"", "Where the participant meets it": "The pre-brief", "Quoted text": "unreachable for at least ninety minutes"}], "source_sheet": {"d2_situation_class": "SC-D2-6", "workplace_demand": "Holding a client-facing matter that exceeds the participant''s authority and knowledge.", "relevant_conduct": "What was stated about who holds the outage and the payroll outcome; what was stated to the human resources director and what it contained; when; the account of the engineering position; whether engineering or the supervisor was named as cause; what step was named and who carries it; what was committed against the 5:00 PM constraint; the answer at B6.", "irrelevant_conduct": "The technical cause of the outage; whether the participant sounds calm; the client organization''s own escalation threat.", "stated_standard": "\"payroll must run by 5:00 PM or two hundred people are not paid on time.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"payroll must run by 5:00 PM or two hundred people are not paid on time\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only. Accommodations changing channel or pause window are recorded and set `timing_not_comparable`.", "unsupported_inferences": "That the participant should or should not have promised a time; that not reaching the supervisor was a failure; anything about composure under workplace pressure.", "compatibility_class": "S2-SEVEN-BEAT", "item_ownership_state": "Contested. The outage is engineering''s; the client relationship is the participant''s.", "knowledge_point": "12:45 PM, when engineering said it could not give an estimate. Exact pre-brief text.", "impact_point": "5:00 PM, the payroll run.", "enquiry_point": "B3", "enquiry_note": null, "knowledge_test_point": "B6", "affected_party": "the client organization''s human resources director", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state the absence of an engineering estimate to the human resources director"}, {"id": "ACT2", "text": "state that the supervisor is unreachable and name when they will be reachable"}, {"id": "ACT3", "text": "commit to a call-back time within the session"}], "material_disclosure_items": [{"id": "MD1", "text": "that engineering has given no resolution estimate"}, {"id": "MD2", "text": "that the participant cannot resolve it themselves"}, {"id": "MD3", "text": "that the supervisor is unreachable for at least ninety minutes"}], "causal_record_set": [{"id": "CR1", "text": "the outage began two hours ago"}, {"id": "CR2", "text": "engineering is aware and has given no estimate"}, {"id": "CR3", "text": "the participant asked for an estimate at 12:45 PM"}], "attribution_support_set": [{"id": "AS1", "text": "engineering has not provided a resolution estimate"}], "accountable_actor_set": [{"id": "AA1", "text": "the engineering team"}, {"id": "AA2", "text": "the supervisor"}], "constraint_set": [{"id": "CS1", "text": "\"by 5:00 PM\""}, {"id": "CS2", "text": "\"unreachable for at least ninety minutes\""}], "list_note": "Not selectable, planning content only: escalate to engineering after the call.", "source_note": null, "situation_class_label": "A matter beyond the person''s authority, knowledge or resources, with time short", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D2-S2-001", "stage_code": "S2", "source_version_hash": "f9e50af837ac3fec066f8e4e4d29c76f16a5c833c9eb7d6460f3bb5cdf12bf67", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S2-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S2-002', 'source'::public.t3a_content_family, 'THE MIGRATION THE SUPERVISOR THINKS IS FINE', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE MIGRATION THE SUPERVISOR THINKS IS FINE", "source_digest": "5577b20d76517351fb57a49db163247c74e934b8d3c4331412c9472da6b8288b", "mentor_brief": "The mentor reads the scripted lines of the supervisor. The supervisor believes the migration is going acceptably. The mentor MUST NOT raise the mismatch rate, the warehouse teams, the daily cost or the vendor''s estimate at any point before B6. If the participant does not raise them, the session runs to B7 unchanged and that is a valid observation. No expressive reaction to any figure.", "participant_pre_brief": "You are an operations analyst.\n\nTwo weeks ago your supervisor approved your proposal to move to new inventory management software. You made the business case and persuaded the leadership team. The migration began last week.\n\nOn Thursday you pulled the reconciliation report and saw the position:\n\n- 45 per cent of inventory records have data mismatches - Three warehouse teams cannot process shipments - Delayed orders are costing approximately eight thousand dollars a day - The vendor''s support team has said a full fix will take five to seven business days\n\nYour supervisor does not know the extent of this. Their understanding is that the migration is going acceptably with a few problems.\n\nYou have a scheduled one-to-one with your supervisor now.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Good to catch up. This is our regular one-to-one. I have a couple of things and then it is over to you.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C3a", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4a", "state": "open"}, {"set": "C4b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "How is the inventory migration going?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C3a", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4a", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5a", "state": "open"}]}, {"beat": "B4", "type": "ASK", "spoken": "The leadership team will ask me for a position on Friday. What do I tell them?", "direction": "Read once, verbatim.", "capture": [{"set": "C8a", "state": "open"}, {"set": "C3b", "state": "update"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would you want done about it, and who does that?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C7a", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have the sequence right — when did you first see the mismatch rate on the reconciliation report?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}, {"set": "C5a", "state": "update"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C6b", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is everything from me. Thanks.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3a", "state": "final"}, {"set": "C4a", "state": "final"}, {"set": "C5a", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C7a", "state": "final"}, {"set": "C8a", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The participant proposed and holds the migration"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "ACT-01 to ACT-03 eligible; ACT-04 NOT eligible"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The affected party is in the room"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "FOUR MATERIAL ITEMS — the richest CE-D2-03 source in the Stage 2 bank"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point already running"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point at B3, so both values reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty but NARROW — only the fix delay is supported"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Attributing the mismatch rate to the vendor resolves to UNSUPPORTED_ATTRIBUTION"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 invites a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 requests a position against a stated date"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at B6"}], "material_map": [{"Item": "MD1", "Item text": "that 45 per cent of records have mismatches", "Where the participant meets it": "The pre-brief", "Quoted text": "per cent of inventory records have data mismatches"}, {"Item": "MD2", "Item text": "that three warehouse teams cannot process shipments", "Where the participant meets it": "The pre-brief", "Quoted text": "Three warehouse teams cannot process shipments - Delayed orders are costing approximately eight thousand dollars a day - The vendor''s support team"}, {"Item": "MD3", "Item text": "that delayed orders cost about eight thousand dollars a day", "Where the participant meets it": "The pre-brief", "Quoted text": "Delayed orders are costing approximately eight thousand dollars a day - The vendor''s support team has said a full fix will take"}, {"Item": "MD4", "Item text": "that the vendor estimates five to seven business days", "Where the participant meets it": "The pre-brief", "Quoted text": "day - The vendor''s support team has said a full fix will take five to seven business days"}, {"Item": "CR1", "Item text": "the migration began last week", "Where the participant meets it": "The pre-brief", "Quoted text": "migration began last week"}, {"Item": "CR2", "Item text": "45 per cent of records have mismatches", "Where the participant meets it": "The pre-brief", "Quoted text": "per cent of inventory records have data mismatches"}, {"Item": "CR3", "Item text": "the vendor''s support team estimates five to seven business days for a full fix", "Where the participant meets it": "The pre-brief", "Quoted text": "eight thousand dollars a day - The vendor''s support team has said a full fix will take five to seven business days"}, {"Item": "AS1", "Item text": "the vendor''s support team has not delivered a fix", "Where the participant meets it": "The pre-brief", "Quoted text": "teams cannot process shipments - Delayed orders are costing approximately eight thousand dollars a day - The vendor''s support team has said"}, {"Item": "CS1", "Item text": "\"five to seven business days\"", "Where the participant meets it": "The pre-brief", "Quoted text": "five to seven business days"}, {"Item": "CS2", "Item text": "\"Friday\"", "Where the participant meets it": "Beat B4", "Quoted text": "Friday. What do I"}], "source_sheet": {"d2_situation_class": "SC-D2-2", "workplace_demand": "Surfacing the failure of a change the participant themselves championed.", "relevant_conduct": "What was stated about holding the migration; whether the four figures were stated and which; when in the session; the account of cause; whether the vendor or the software was named; the step named and its holder; what was committed for Friday; the answer at B6.", "irrelevant_conduct": "The merits of the software choice; whether the original business case was sound; the vendor''s competence.", "stated_standard": "\"a full fix will take five to seven business days.\" Exact pre-brief text, the vendor''s stated position.", "stated_standard_source_quote_or_location": "\"a full fix will take five to seven business days\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded and set `timing_not_comparable`.", "unsupported_inferences": "That the participant was hiding the position; that championing the change makes them culpable; anything about willingness to admit error.", "compatibility_class": "S2-SEVEN-BEAT", "item_ownership_state": "Held_by_participant.", "knowledge_point": "Thursday, on pulling the reconciliation report.", "impact_point": "Already running. Eight thousand dollars a day is accruing at the moment of the session, so THE IMPACT POINT PRECEDES THE SESSION and Q-D2-04a A1 is unreachable.", "enquiry_point": "B3", "enquiry_note": null, "knowledge_test_point": "B6", "affected_party": "the supervisor", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state the mismatch rate to the supervisor"}, {"id": "ACT2", "text": "state the daily cost"}, {"id": "ACT3", "text": "state the vendor''s five-to-seven-day estimate"}], "material_disclosure_items": [{"id": "MD1", "text": "that 45 per cent of records have mismatches"}, {"id": "MD2", "text": "that three warehouse teams cannot process shipments"}, {"id": "MD3", "text": "that delayed orders cost about eight thousand dollars a day"}, {"id": "MD4", "text": "that the vendor estimates five to seven business days"}], "causal_record_set": [{"id": "CR1", "text": "the migration began last week"}, {"id": "CR2", "text": "45 per cent of records have mismatches"}, {"id": "CR3", "text": "the vendor''s support team estimates five to seven business days for a full fix"}], "attribution_support_set": [{"id": "AS1", "text": "the vendor''s support team has not delivered a fix"}], "accountable_actor_set": [{"id": "AA1", "text": "the supervisor"}, {"id": "AA2", "text": "the vendor"}], "constraint_set": [{"id": "CS1", "text": "\"five to seven business days\""}, {"id": "CS2", "text": "\"Friday\""}], "list_note": "Not selectable, planning content only: pause the migration. The record does NOT support attributing the mismatch rate itself to the vendor.", "source_note": null, "situation_class_label": "A shortfall the person contributed to, not yet known to the affected party, with its cause on record", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D2-S2-002", "stage_code": "S2", "source_version_hash": "5577b20d76517351fb57a49db163247c74e934b8d3c4331412c9472da6b8288b", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S2-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S2-003', 'source'::public.t3a_content_family, 'THE DASHBOARD NOBODY HANDED OVER', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE DASHBOARD NOBODY HANDED OVER", "source_digest": "ee2524247b70cdffd42ee37ba46cdbd35349d9033d4b54e98ba85c75eee00f06", "mentor_brief": "The mentor reads the scripted lines of the client organization''s contact. The mentor does not know the colleague is on leave and must not say so. The mentor must not press, escalate or repeat. If the participant explains the colleague''s absence, the mentor does not respond to it and proceeds to the next scripted beat.", "participant_pre_brief": "You work in client services.\n\nThe client organization was promised a custom analytics dashboard by a colleague who is now on leave for two weeks. It was due last Friday.\n\nYou checked the system this morning. There are no notes, no progress files and no handover documentation. The contract does record that the dashboard was promised.\n\nYou have not worked on this client organization''s account before.\n\nTheir contact is calling now.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Thank you for picking this up. We were told the dashboard would be ready last Friday. I will let you begin.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C3a", "state": "open"}, {"set": "C4a", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Where does the dashboard stand?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C3a", "state": "update"}, {"set": "C3b", "state": "open"}, {"set": "C4a", "state": "update"}, {"set": "C4b", "state": "open"}, {"set": "C5a", "state": "open"}, {"set": "C6a", "state": "open"}]}, {"beat": "B4", "type": "ASK", "spoken": "We have a board meeting next Thursday and we need the data. Can you give me a date?", "direction": "Read once, verbatim.", "capture": [{"set": "C8a", "state": "open"}]}, {"beat": "B5", "type": "ASK", "spoken": "What happens next, and who is doing it?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C7a", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have the sequence right — when did you first see there was no handover material for this account?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}, {"set": "C5a", "state": "update"}, {"set": "C5b", "state": "open"}, {"set": "C6b", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. I will wait to hear.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3a", "state": "final"}, {"set": "C4a", "state": "final"}, {"set": "C5a", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C7a", "state": "final"}, {"set": "C8a", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "item_ownership_state is unassigned; B2 and B3 create the opportunity. THIS IS THE STRONGEST CE-D2-01 SOURCE IN THE STAGE 2 BANK"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "ACT-01 to ACT-03 eligible"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The affected party is on the call"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point already passed"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point at B3"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty and the attribution is SUPPORTED. A participant who names the handover gap is stating what the record states"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "The absent colleague is NEVER NAMED in any rendered statement"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 invites a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 requests a date against a stated constraint"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at B6"}], "material_map": [{"Item": "MD1", "Item text": "that the delivery date was missed", "Where the participant meets it": "The pre-brief", "Quoted text": "It was due last Friday"}, {"Item": "MD2", "Item text": "that there is no handover material", "Where the participant meets it": "Beat B6", "Quoted text": "handover material for this"}, {"Item": "MD3", "Item text": "that the participant has not worked on the account before", "Where the participant meets it": "The pre-brief", "Quoted text": "worked on this client organization''s account"}, {"Item": "CR1", "Item text": "the dashboard was promised in the contract", "Where the participant meets it": "The pre-brief", "Quoted text": "contract does record that the dashboard was promised"}, {"Item": "CR2", "Item text": "it was due last Friday", "Where the participant meets it": "The pre-brief", "Quoted text": "was due last Friday"}, {"Item": "CR3", "Item text": "no notes, progress files or handover documentation exist", "Where the participant meets it": "The pre-brief", "Quoted text": "notes, no progress files and no handover documentation"}, {"Item": "CR4", "Item text": "the colleague who promised it is on leave for two weeks", "Where the participant meets it": "The pre-brief", "Quoted text": "promised a custom analytics dashboard by a colleague who is now on leave for two weeks"}, {"Item": "AS1", "Item text": "no handover documentation was left", "Where the participant meets it": "The pre-brief", "Quoted text": "and no handover documentation"}, {"Item": "AS2", "Item text": "the colleague who made the commitment is on leave", "Where the participant meets it": "The pre-brief", "Quoted text": "colleague who is now on leave"}, {"Item": "CS1", "Item text": "\"next Thursday\"", "Where the participant meets it": "Beat B4", "Quoted text": "next Thursday and we"}], "source_sheet": {"d2_situation_class": "SC-D2-5", "workplace_demand": "Holding a client commitment made by someone else and documented by no one.", "relevant_conduct": "What was stated about who holds the dashboard now; what was stated to the client contact and what it contained; the account of the handover position; whether the absent colleague was named; the step and its holder; the date committed against the board meeting; the answer at B6.", "irrelevant_conduct": "The absent colleague''s conduct or character; the technical scope of the dashboard; the client organization''s tone.", "stated_standard": "\"The contract does record that the dashboard was promised\"; \"due last Friday.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"The contract does record that the dashboard was promised\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That the absent colleague failed; that naming them is deflection; that the participant should absorb the work.", "compatibility_class": "S2-SEVEN-BEAT", "item_ownership_state": "Unassigned. Nobody currently holds it.", "knowledge_point": "This morning, on checking the system.", "impact_point": "Last Friday, the promised delivery date, already passed.", "enquiry_point": "B3", "enquiry_note": null, "knowledge_test_point": "B6", "affected_party": "the client organization''s contact", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state that there is no handover material"}, {"id": "ACT2", "text": "state that the participant will hold the item"}, {"id": "ACT3", "text": "commit a date in the session"}], "material_disclosure_items": [{"id": "MD1", "text": "that the delivery date was missed"}, {"id": "MD2", "text": "that there is no handover material"}, {"id": "MD3", "text": "that the participant has not worked on the account before"}], "causal_record_set": [{"id": "CR1", "text": "the dashboard was promised in the contract"}, {"id": "CR2", "text": "it was due last Friday"}, {"id": "CR3", "text": "no notes, progress files or handover documentation exist"}, {"id": "CR4", "text": "the colleague who promised it is on leave for two weeks"}], "attribution_support_set": [{"id": "AS1", "text": "no handover documentation was left"}, {"id": "AS2", "text": "the colleague who made the commitment is on leave"}], "accountable_actor_set": [{"id": "AA1", "text": "the absent colleague"}, {"id": "AA2", "text": "the client organization"}], "constraint_set": [{"id": "CS1", "text": "\"next Thursday\""}], "list_note": "Not selectable, planning content only: rebuild the dashboard. Exact text at B4.", "source_note": null, "situation_class_label": "A shortfall arising from another person''s work or an inherited state the person now holds", "observation_mode_label": "structured_live_session", "min_seconds": 420, "max_seconds": 900}, "source_identifier": "SRC-D2-S2-003", "stage_code": "S2", "source_version_hash": "ee2524247b70cdffd42ee37ba46cdbd35349d9033d4b54e98ba85c75eee00f06", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S2-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S2-005', 'source'::public.t3a_content_family, 'THE WORKFLOW IN THE QUARTERLY UPDATE', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE WORKFLOW IN THE QUARTERLY UPDATE", "source_digest": "8271c0469980c3a826be8e3bf76d0f19f07dad1bca599f6c0cdbf567ab01ffd4", "mentor_brief": "The mentor reads the scripted lines of the supervisor presenting, and then the vice-president''s question, both from the script. The mentor addresses the room, not the participant, until B3. The mentor MUST NOT look at or gesture towards the participant during B1 and B2. No expressive reaction at any point.", "participant_pre_brief": "You are a junior analyst.\n\nOver the past month you designed, tested and implemented a new client onboarding workflow. You gathered the feedback and made the changes yourself. Onboarding time is down by thirty per cent. The change log records your name against every revision.\n\nYour supervisor is presenting the quarterly department update to the vice-president and the director team. You are in the room.", "script": [{"beat": "B1", "type": "SAY", "spoken": "One of the wins this quarter is the new client onboarding workflow. The team has been streamlining the process and onboarding time is down thirty per cent. It has been a real team effort.\" Then, as the vice-president: \"Impressive. Who led this?\" Then, as the supervisor: \"It was a collaborative effort across the team.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C3a", "state": "open"}, {"set": "C6a", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "Was there anything you wanted to add to that item?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C3a", "state": "update"}, {"set": "C3b", "state": "open"}, {"set": "C4a", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C5a", "state": "open"}]}, {"beat": "B4", "type": "ASK", "spoken": "The vice-president will want a name against this for the record. What should it say?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C6a", "state": "update"}, {"set": "C8a", "state": "open"}]}, {"beat": "B5", "type": "ASK", "spoken": "What would you want done differently on the next update, and who does that?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C7a", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have the sequence right — when did you first see that the slide did not carry your name?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}, {"set": "C5a", "state": "update"}, {"set": "C5b", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Noted. Thank you.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3a", "state": "final"}, {"set": "C4a", "state": "final"}, {"set": "C5a", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C7a", "state": "final"}, {"set": "C8a", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "THIS IS THE PRIMARY ELEMENT OF THIS SOURCE. Ownership is contested and B2, B3 and B4 each create the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Two in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "ACT-01 and ACT-02 eligible; ACT-03 NOT eligible"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The supervisor is present throughout"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "THIS IS THE ONLY SOURCE IN THE BANK WHERE THE TWO POINTS COINCIDE"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "Served because the opportunity is genuine and a substantive attributed-to-no-person option exists"}, {"question": "Q-D2-06b", "state": "NOT SERVED", "basis": "The source designates no attribution_support_set item, so the bound question cannot be offered"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 invites a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 invites a forward statement, though the source supplies no dated constraint"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at B6"}], "material_map": [{"Item": "MD1", "Item text": "that the participant designed, tested and implemented the workflow", "Where the participant meets it": "The pre-brief", "Quoted text": "designed, tested and implemented a new client onboarding workflow"}, {"Item": "MD2", "Item text": "that the change log records their name against every revision", "Where the participant meets it": "The pre-brief", "Quoted text": "change log records your name against every revision"}, {"Item": "CR1", "Item text": "the participant designed, tested and implemented the workflow", "Where the participant meets it": "The pre-brief", "Quoted text": "designed, tested and implemented a new client onboarding workflow"}, {"Item": "CR2", "Item text": "the change log records their name against every revision", "Where the participant meets it": "The pre-brief", "Quoted text": "change log records your name against every revision"}, {"Item": "CR3", "Item text": "the slide stated a team effort", "Where the participant meets it": "Beat B1", "Quoted text": "a real team effort.\""}], "source_sheet": {"d2_situation_class": "SC-D2-7", "workplace_demand": "Stating one''s own holding of work where the record of contribution is contested.", "relevant_conduct": "What was stated about who held the workflow; whether a statement was made to the supervisor and when relative to B2 and B3; what the statement contained; the account of contribution against the change log; the step named and its holder; the answer at B6.", "irrelevant_conduct": "The supervisor''s conduct or motives, which are scripted and are NEVER recorded or rendered; whether the participant seems assertive; the merits of the workflow.", "stated_standard": "\"The change log records your name against every revision.\" Exact pre-brief text. THIS IS THE ONLY RECORD IN THE SOURCE THAT ESTABLISHES CONTRIBUTION.", "stated_standard_source_quote_or_location": "\"The change log records your name against every revision\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That the participant should have spoken or should have stayed silent; that the supervisor took credit; that silence indicates anything about the participant. NONE OF THESE MAY APPEAR IN ANY STATEMENT, NOTE OR FIELD.", "compatibility_class": "S2-SEVEN-BEAT", "item_ownership_state": "Contested.", "knowledge_point": "At B1, when the slide is presented without a name.", "impact_point": "B1, the moment the record is stated to the room.", "enquiry_point": "B3", "enquiry_note": null, "knowledge_test_point": "B6", "affected_party": "the supervisor", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state their own part in the room"}, {"id": "ACT2", "text": "state that the change log records the detail"}], "material_disclosure_items": [{"id": "MD1", "text": "that the participant designed, tested and implemented the workflow"}, {"id": "MD2", "text": "that the change log records their name against every revision"}], "causal_record_set": [{"id": "CR1", "text": "the participant designed, tested and implemented the workflow"}, {"id": "CR2", "text": "the change log records their name against every revision"}, {"id": "CR3", "text": "the slide stated a team effort"}], "attribution_support_set": [], "accountable_actor_set": [{"id": "AA1", "text": "the supervisor"}], "constraint_set": [], "list_note": "Not selectable, planning content only: raise it with the supervisor after the meeting. Recorded as explicit none. THE RECORD SUPPORTS NO ATTRIBUTION OF A SHORTFALL TO ANOTHER PERSON, and the supervisor''s framing is a statement made by a character, not a fact created by the source. Not_applicable. Reason: no forward commitment is requested. Q-D2-08a IS STILL SERVED because B4 invites a statement about the record, and A4 stated-no-commitment is a valid recorded answer.", "source_note": "This source records a participant''s conduct in a setting where the person whose account is contested is their own supervisor, in front of that supervisor''s superiors. The power asymmetry is real and the range of defensible conduct is wide. It must not be approved without the fairness drafting test completed by someone who has read this note, and the statement library must be checked so that no composed statement can read as a judgment about whether the participant should have spoken.", "situation_class_label": "Contested contribution or credit for a piece of work, with a record of who did what", "observation_mode_label": "structured_live_session", "min_seconds": 420, "max_seconds": 900}, "source_identifier": "SRC-D2-S2-005", "stage_code": "S2", "source_version_hash": "8271c0469980c3a826be8e3bf76d0f19f07dad1bca599f6c0cdbf567ab01ffd4", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S2-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S2-007', 'source'::public.t3a_content_family, 'THE MIGRATION THAT WAS ON TRACK', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE MIGRATION THAT WAS ON TRACK", "source_digest": "9d463b3902b7f9ba93490ddcf0a8f9c6bc52ea2db998319561f420cb21d7afa9", "mentor_brief": "The mentor reads the scripted lines of the director. The director knows the migration corrupted records and that the participant was accountable for the deliverable. The director does NOT know about the Wednesday check-in and must not raise it before B6. No escalation, no repetition, no expressive reaction.", "participant_pre_brief": "You are a team lead.\n\nLast week you assigned a critical data migration to a junior team member. You gave written instructions and a Friday deadline.\n\nYou checked in on Wednesday. They told you everything was on track. You recorded that in your check-in log and did not check again.\n\nIt is Monday morning. The migration corrupted about twenty per cent of the client organization''s customer records. They cannot process orders.\n\nYour director is calling now.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I have had a call from the client organization. The data migration corrupted about twenty per cent of their customer records and they cannot process orders. I want to understand it before I call them back. Go ahead.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C3a", "state": "open"}, {"set": "C5a", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C3b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "What happened with the migration?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C5a", "state": "update"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "update"}, {"set": "C6b", "state": "open"}, {"set": "C3a", "state": "update"}]}, {"beat": "B4", "type": "ASK", "spoken": "The client organization wants a recovery position by end of day. Can you give me one?", "direction": "Read once, verbatim.", "capture": [{"set": "C8a", "state": "open"}]}, {"beat": "B5", "type": "ASK", "spoken": "What changes so this does not repeat, and who makes that change?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C7a", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have the sequence right — when did you last have confirmation that the migration was on track?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}, {"set": "C4a", "state": "open"}, {"set": "C4b", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Understood. Thank you.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3a", "state": "final"}, {"set": "C4a", "state": "final"}, {"set": "C5a", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C7a", "state": "final"}, {"set": "C8a", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The director''s B1 statement places the deliverable with the participant"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "ACT-01 to ACT-03 eligible"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The director is on the call"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point already passed; knowledge_point is this morning"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point at B3"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "THE CENTRAL TENSION OF THIS SOURCE. The record supports naming the Wednesday report, and the director''s position is that the deliverable was the participant''s. BOTH CAN BE TRUE AND THE DETERMINATION RECORDS WHICH WAS STATED, NOT WHICH WAS RIGHT"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "The junior team member is NEVER NAMED in a rendered statement"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 invites a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 requests a position against a stated constraint"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at B6"}], "material_map": [{"Item": "MD1", "Item text": "that the deliverable was the participant''s", "Where the participant meets it": "The pre-brief", "Quoted text": "Last week you assigned a critical data migration to a junior team member"}, {"Item": "MD2", "Item text": "that the work was assigned to a junior team member", "Where the participant meets it": "The pre-brief", "Quoted text": "assigned a critical data migration to a junior team member"}, {"Item": "MD3", "Item text": "that a Wednesday check-in reported on track and was logged", "Where the participant meets it": "The pre-brief", "Quoted text": "checked in on Wednesday"}, {"Item": "CR1", "Item text": "the migration was assigned to a junior team member with written instructions and a Friday deadline", "Where the participant meets it": "The pre-brief", "Quoted text": "assigned a critical data migration to a junior team member"}, {"Item": "CR2", "Item text": "a Wednesday check-in reported on track and was recorded", "Where the participant meets it": "The pre-brief", "Quoted text": "checked in on Wednesday"}, {"Item": "CR3", "Item text": "no further check was made", "Where the participant meets it": "The pre-brief", "Quoted text": "and did not check again"}, {"Item": "CR4", "Item text": "about twenty per cent of records were corrupted", "Where the participant meets it": "Beat B1", "Quoted text": "corrupted about twenty per cent of their customer records"}, {"Item": "AS1", "Item text": "the junior team member reported on track at the Wednesday check-in", "Where the participant meets it": "The pre-brief", "Quoted text": "a junior team member"}, {"Item": "CS1", "Item text": "\"by end of day\"", "Where the participant meets it": "Beat B4", "Quoted text": "by end of day"}], "source_sheet": {"d2_situation_class": "SC-D2-4", "workplace_demand": "Accounting for a deliverable the participant held but did not perform.", "relevant_conduct": "What was stated about who held the deliverable; the account of cause against the record; whether the junior team member was named and whether the naming matches the support set; the step named and its holder; the recovery commitment; the answer at B6.", "irrelevant_conduct": "The junior team member''s competence; the technical nature of the corruption; whether delegation was wise.", "stated_standard": "\"You gave written instructions and a Friday deadline.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"You gave written instructions and a Friday deadline\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That the participant should have checked again on Thursday; that the junior team member misled them; that delegation was the cause.", "compatibility_class": "S2-SEVEN-BEAT", "item_ownership_state": "Held_by_participant. The director''s position at B1 establishes it.", "knowledge_point": "Monday morning, when the director called. THE PARTICIPANT DID NOT KNOW BEFORE THIS.", "impact_point": "Friday, the migration deadline, already passed.", "enquiry_point": null, "enquiry_note": "B1, in the opening. NOTE: B1 IS NOT A QUESTION — it is a statement followed by \"Go ahead\", which does not ask about the shortfall. The enquiry is B3.", "knowledge_test_point": "B6", "affected_party": "the director", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state that the deliverable was theirs"}, {"id": "ACT2", "text": "state the Wednesday check-in and what was recorded"}, {"id": "ACT3", "text": "commit a recovery position in the session"}], "material_disclosure_items": [{"id": "MD1", "text": "that the deliverable was the participant''s"}, {"id": "MD2", "text": "that the work was assigned to a junior team member"}, {"id": "MD3", "text": "that a Wednesday check-in reported on track and was logged"}], "causal_record_set": [{"id": "CR1", "text": "the migration was assigned to a junior team member with written instructions and a Friday deadline"}, {"id": "CR2", "text": "a Wednesday check-in reported on track and was recorded"}, {"id": "CR3", "text": "no further check was made"}, {"id": "CR4", "text": "about twenty per cent of records were corrupted"}], "attribution_support_set": [{"id": "AS1", "text": "the junior team member reported on track at the Wednesday check-in"}], "accountable_actor_set": [{"id": "AA1", "text": "the junior team member"}, {"id": "AA2", "text": "the director"}], "constraint_set": [{"id": "CS1", "text": "\"by end of day\""}], "list_note": "Not selectable, planning content only: restore the records. Exact text at B4.", "source_note": null, "situation_class_label": "A completed failure under review, with contribution spread across several people on record", "observation_mode_label": "structured_live_session", "min_seconds": 480, "max_seconds": 900}, "source_identifier": "SRC-D2-S2-007", "stage_code": "S2", "source_version_hash": "9d463b3902b7f9ba93490ddcf0a8f9c6bc52ea2db998319561f420cb21d7afa9", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S2-007' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S2-008', 'source'::public.t3a_content_family, 'THE REPORT AGAINST THE BRIEF', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE REPORT AGAINST THE BRIEF", "source_digest": "67a7ac0608f88c3407376b9dd143ecbf9f5acc5e4e0e1a24fb5a74e15ec95bb4", "mentor_brief": "The mentor reads the scripted lines of the supervisor. The mentor reads the scripted text and does not defend, repeat or expand the brief beyond it. If the participant quotes the original brief, the mentor does not respond to that and proceeds to the next scripted beat. No expressive reaction.", "participant_pre_brief": "You are a marketing analyst.\n\nThree weeks ago your supervisor asked you for a social media engagement report for the quarterly review. The written brief said: focus on follower growth, engagement rates and top-performing posts across the two main channels.\n\nYou kept that brief. You delivered the report yesterday, on time, covering exactly those three things.\n\nYour supervisor has asked to see you now.", "script": [{"beat": "B1", "type": "SAY", "spoken": "I have reviewed the social media report. It does not have competitive benchmarking against our top three competitors, and there is no return analysis tying engagement to lead generation. As it stands it does not meet the standard for the quarterly review. I will let you respond.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C3a", "state": "open"}, {"set": "C5a", "state": "open"}, {"set": "C6a", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "How did you scope the report?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C5a", "state": "update"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "update"}, {"set": "C6b", "state": "open"}]}, {"beat": "B4", "type": "ASK", "spoken": "The quarterly review is on Thursday. Can you get me the benchmarking and the return analysis by then?", "direction": "Read once, verbatim.", "capture": [{"set": "C8a", "state": "open"}]}, {"beat": "B5", "type": "ASK", "spoken": "What changes for the next one, and who makes that change?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C7a", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have the sequence right — when did you last see the written brief before you delivered?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}, {"set": "C4a", "state": "open"}, {"set": "C4b", "state": "open"}, {"set": "C3a", "state": "update"}, {"set": "C3b", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Understood. Thank you.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3a", "state": "final"}, {"set": "C4a", "state": "final"}, {"set": "C5a", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C7a", "state": "final"}, {"set": "C8a", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "Ownership of the scope decision is contested; B2 and B3 create the opportunity"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "ACT-01 to ACT-03 eligible"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The supervisor is in the room"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point at B3, both values reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty. THE ACCOUNT CAN CORRESPOND EXACTLY, because the brief is the record and the participant kept it"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty and SUPPORTED. Naming the brief is stating what the record states, not shifting blame"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "THE SUPERVISOR IS NEVER NAMED IN A RENDERED STATEMENT"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 invites a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 requests a commitment against a stated date"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at B6"}], "material_map": [{"Item": "MD1", "Item text": "that the written brief named three items", "Where the participant meets it": "The pre-brief", "Quoted text": "written brief said: focus"}, {"Item": "MD2", "Item text": "that benchmarking and return analysis were not in it", "Where the participant meets it": "Beat B4", "Quoted text": "benchmarking and the return analysis"}, {"Item": "MD3", "Item text": "that the delivered report covers the three briefed items", "Where the participant meets it": "The pre-brief", "Quoted text": "delivered the report yesterday, on time, covering exactly those three"}, {"Item": "CR1", "Item text": "the written brief named three items", "Where the participant meets it": "The pre-brief", "Quoted text": "written brief said: focus"}, {"Item": "CR2", "Item text": "the report covers those three items", "Where the participant meets it": "The pre-brief", "Quoted text": "report yesterday, on time, covering exactly those three"}, {"Item": "CR3", "Item text": "benchmarking and return analysis were not named in the brief", "Where the participant meets it": "Beat B4", "Quoted text": "benchmarking and the return analysis"}, {"Item": "AS1", "Item text": "the written brief did not name benchmarking or return analysis", "Where the participant meets it": "Beat B4", "Quoted text": "benchmarking and the return analysis"}, {"Item": "CS1", "Item text": "\"on Thursday\"", "Where the participant meets it": "Beat B4", "Quoted text": "on Thursday. Can you"}], "source_sheet": {"d2_situation_class": "SC-D2-4", "workplace_demand": "Holding a gap between a written brief and an unstated expectation.", "relevant_conduct": "What was stated about who held the scope decision; what was stated to the supervisor and when; the account of scoping against the written brief; whether the brief or the supervisor was named as cause; the step and its holder; the commitment against Thursday; the answer at B6.", "irrelevant_conduct": "Whether the supervisor''s expectation was reasonable; the merits of benchmarking as a practice; whether the participant seems defensive.", "stated_standard": "\"focus on follower growth, engagement rates and top-performing posts across the two main channels.\" Exact pre-brief text, THE WRITTEN BRIEF. Nothing in the source establishes benchmarking or return analysis as a requirement before B1.", "stated_standard_source_quote_or_location": "\"focus on follower growth, engagement rates and top-performing posts across the two main channels\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That the participant should have anticipated the unstated items; that the supervisor moved the brief; that quoting the brief is defensiveness or that not quoting it is maturity.", "compatibility_class": "S2-SEVEN-BEAT", "item_ownership_state": "Contested. The participant held the report; the standard it is being measured against was not in the brief.", "knowledge_point": "B1. THE PARTICIPANT DID NOT KNOW OF THE GAP UNTIL THE SUPERVISOR STATED IT.", "impact_point": "Thursday, the quarterly review.", "enquiry_point": "B3", "enquiry_note": null, "knowledge_test_point": "B6", "affected_party": "the supervisor", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state what the written brief contained"}, {"id": "ACT2", "text": "state that the two items are absent"}, {"id": "ACT3", "text": "commit a date in session"}], "material_disclosure_items": [{"id": "MD1", "text": "that the written brief named three items"}, {"id": "MD2", "text": "that benchmarking and return analysis were not in it"}, {"id": "MD3", "text": "that the delivered report covers the three briefed items"}], "causal_record_set": [{"id": "CR1", "text": "the written brief named three items"}, {"id": "CR2", "text": "the report covers those three items"}, {"id": "CR3", "text": "benchmarking and return analysis were not named in the brief"}], "attribution_support_set": [{"id": "AS1", "text": "the written brief did not name benchmarking or return analysis"}], "accountable_actor_set": [{"id": "AA1", "text": "the supervisor"}], "constraint_set": [{"id": "CS1", "text": "\"on Thursday\""}], "list_note": "Not selectable, planning content only: produce the benchmarking. Exact text at B4.", "source_note": null, "situation_class_label": "A completed failure under review, with contribution spread across several people on record", "observation_mode_label": "structured_live_session", "min_seconds": 420, "max_seconds": 900}, "source_identifier": "SRC-D2-S2-008", "stage_code": "S2", "source_version_hash": "67a7ac0608f88c3407376b9dd143ecbf9f5acc5e4e0e1a24fb5a74e15ec95bb4", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S2-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S2-009', 'source'::public.t3a_content_family, 'THE DEVELOPER LEAVING IN WEEK SIX', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE DEVELOPER LEAVING IN WEEK SIX", "source_digest": "99e8d44d5a10bce6ec6cc74ef294c875ca83a9cd276042fb852d04fcb8849d6f", "mentor_brief": "The mentor reads the scripted lines of the supervisor. The supervisor does NOT know about the resignation and must not raise it, allude to it or react expressively to it. If the participant does not raise it, the session runs to B7 unchanged and that is a valid observation.", "participant_pre_brief": "You are a project manager leading a twelve-week implementation for the client organization. The project is in week six, the build phase.\n\nThis morning the lead developer told you they have accepted another job. Their last day is Friday — four days away. They carry about forty per cent of the technical work on the project.\n\nYou have not told anyone else yet.\n\nYour supervisor''s weekly project check-in is now.", "script": [{"beat": "B1", "type": "SAY", "spoken": "This is the weekly check-in on the implementation. I have the schedule in front of me. Over to you.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C3a", "state": "open"}, {"set": "C3b", "state": "open"}, {"set": "C4a", "state": "open"}, {"set": "C4b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "How is the build phase running?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C3a", "state": "update"}, {"set": "C3b", "state": "update"}, {"set": "C4a", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5a", "state": "open"}]}, {"beat": "B4", "type": "ASK", "spoken": "The client organization has the week-twelve date in their plan. Can we still hold it?", "direction": "Read once, verbatim.", "capture": [{"set": "C8a", "state": "open"}]}, {"beat": "B5", "type": "ASK", "spoken": "What needs to happen, and who does it?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C7a", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have the sequence right — when did you first know the lead developer was leaving?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}, {"set": "C5a", "state": "update"}, {"set": "C5b", "state": "open"}, {"set": "C6a", "state": "open"}, {"set": "C6b", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "That is everything from me. Thanks.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3a", "state": "final"}, {"set": "C4a", "state": "final"}, {"set": "C5a", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C7a", "state": "final"}, {"set": "C8a", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The participant leads the implementation"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "ACT-01 to ACT-03 eligible"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The affected party is in the room and does not know"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "knowledge_point this morning, impact_point week twelve"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty and supported"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "The departing developer is NEVER NAMED in a rendered statement"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 invites a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "accountable_actor_set includes the supervisor, so a participant may state the holder is not themselves"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 requests a commitment against the week-twelve date"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at B6"}], "material_map": [{"Item": "MD1", "Item text": "that the lead developer has resigned", "Where the participant meets it": "The pre-brief", "Quoted text": "lead developer told you"}, {"Item": "MD2", "Item text": "that their last day is Friday", "Where the participant meets it": "The pre-brief", "Quoted text": "last day is Friday — four days"}, {"Item": "MD3", "Item text": "that they carry about forty per cent of the technical work", "Where the participant meets it": "The pre-brief", "Quoted text": "carry about forty per cent of the technical work"}, {"Item": "CR1", "Item text": "the lead developer accepted another job", "Where the participant meets it": "The pre-brief", "Quoted text": "lead developer told you they have accepted another job"}, {"Item": "CR2", "Item text": "their last day is Friday", "Where the participant meets it": "The pre-brief", "Quoted text": "last day is Friday — four days"}, {"Item": "CR3", "Item text": "they carry about forty per cent of the technical work", "Where the participant meets it": "The pre-brief", "Quoted text": "carry about forty per cent of the technical work"}, {"Item": "CR4", "Item text": "the project is in week six of twelve", "Where the participant meets it": "The pre-brief", "Quoted text": "project is in week six"}, {"Item": "AS1", "Item text": "the lead developer resigned during the build phase", "Where the participant meets it": "The pre-brief", "Quoted text": "six, the build phase"}, {"Item": "CS1", "Item text": "\"twelve-week\"", "Where the participant meets it": "The pre-brief", "Quoted text": "twelve-week implementation for the"}, {"Item": "CS2", "Item text": "\"the week-twelve date\"", "Where the participant meets it": "Beat B4", "Quoted text": "the week-twelve date in"}, {"Item": "CS3", "Item text": "\"last day is Friday\"", "Where the participant meets it": "The pre-brief", "Quoted text": "last day is Friday"}], "source_sheet": {"d2_situation_class": "SC-D2-6", "workplace_demand": "Surfacing a resource loss that the participant alone knows about.", "relevant_conduct": "What was stated about who holds the schedule risk; whether the resignation was stated and when; what the statement contained; the account of the position; whether the departing developer was named as cause; the step and its holder; the commitment against week twelve; the answer at B6.", "irrelevant_conduct": "The departing developer''s reasons or conduct; the merits of the resourcing plan; whether the participant appears worried.", "stated_standard": "\"a twelve-week implementation\"; \"Their last day is Friday.\" Exact pre-brief text.", "stated_standard_source_quote_or_location": "\"a twelve-week implementation\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That the participant should have foreseen the resignation; that not raising it at B2 is withholding; that the developer let the team down.", "compatibility_class": "S2-SEVEN-BEAT", "item_ownership_state": "Held_by_participant.", "knowledge_point": "This morning, when the lead developer told the participant.", "impact_point": "Week twelve, the client organization''s date. THE IMPACT POINT IS IN THE FUTURE, so A1 is reachable.", "enquiry_point": "B3", "enquiry_note": null, "knowledge_test_point": "B6", "affected_party": "the supervisor", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state the resignation to the supervisor"}, {"id": "ACT2", "text": "state the forty per cent coverage figure"}, {"id": "ACT3", "text": "ask the supervisor for a named replacement or a date change"}], "material_disclosure_items": [{"id": "MD1", "text": "that the lead developer has resigned"}, {"id": "MD2", "text": "that their last day is Friday"}, {"id": "MD3", "text": "that they carry about forty per cent of the technical work"}], "causal_record_set": [{"id": "CR1", "text": "the lead developer accepted another job"}, {"id": "CR2", "text": "their last day is Friday"}, {"id": "CR3", "text": "they carry about forty per cent of the technical work"}, {"id": "CR4", "text": "the project is in week six of twelve"}], "attribution_support_set": [{"id": "AS1", "text": "the lead developer resigned during the build phase"}], "accountable_actor_set": [{"id": "AA1", "text": "the supervisor"}, {"id": "AA2", "text": "the client organization"}], "constraint_set": [{"id": "CS1", "text": "\"twelve-week\""}, {"id": "CS2", "text": "\"the week-twelve date\""}, {"id": "CS3", "text": "\"last day is Friday\""}], "list_note": "Not selectable, planning content only: run a handover with the departing developer.", "source_note": null, "situation_class_label": "A matter beyond the person''s authority, knowledge or resources, with time short", "observation_mode_label": "structured_live_session", "min_seconds": 420, "max_seconds": 900}, "source_identifier": "SRC-D2-S2-009", "stage_code": "S2", "source_version_hash": "99e8d44d5a10bce6ec6cc74ef294c875ca83a9cd276042fb852d04fcb8849d6f", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S2-009' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S2-010', 'source'::public.t3a_content_family, 'THE PRICING COMPARISON NEVER SENT', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 2, "title": "THE PRICING COMPARISON NEVER SENT", "source_digest": "d6940d63994b7ab61c28ddf3801f28b1b7b8c641b9a286755f1fcb6f1661c593", "mentor_brief": "The mentor reads the scripted lines of the operations director. The mentor raises the pricing comparison at B3 as scripted, and not before. The mentor must not express disappointment, must not repeat, and must not add the consequence beyond the scripted line.", "participant_pre_brief": "You are an account coordinator.\n\nTwo weeks ago, on a call with the client organization, their operations director asked you for a pricing comparison across three service tiers. You said you would have it to them by the end of the following week. It is in your notes from that call.\n\nYou did not send it. You have not thought about it since.\n\nThere is a regular check-in call with the operations director now. Your supervisor is on the call.", "script": [{"beat": "B1", "type": "SAY", "spoken": "Thanks both for the time. This is our regular check-in. I have one item from my side and then whatever you have.", "direction": null, "capture": []}, {"beat": "B2", "type": "PAUSE", "spoken": null, "direction": "Say nothing for ten to fifteen seconds. Do not prompt or fill the silence.", "capture": [{"set": "C1", "state": "open"}, {"set": "C3a", "state": "open"}, {"set": "C4a", "state": "open"}, {"set": "C4b", "state": "open"}]}, {"beat": "B3", "type": "ASK", "spoken": "I never received the pricing comparison you said you would send two weeks ago. Where does that stand?", "direction": "Read once, verbatim.", "capture": [{"set": "C1", "state": "update"}, {"set": "C3a", "state": "update"}, {"set": "C3b", "state": "open"}, {"set": "C4a", "state": "update"}, {"set": "C4b", "state": "update"}, {"set": "C5a", "state": "open"}, {"set": "C6a", "state": "open"}]}, {"beat": "B4", "type": "ASK", "spoken": "We have been holding a decision on expanding the contract while we waited. When can I have it?", "direction": "Read once, verbatim.", "capture": [{"set": "C8a", "state": "open"}]}, {"beat": "B5", "type": "ASK", "spoken": "What happens next, and who is doing it?", "direction": "Read once, verbatim.", "capture": [{"set": "C2", "state": "open"}, {"set": "C2b", "state": "open"}, {"set": "C7a", "state": "open"}, {"set": "C7b", "state": "open"}]}, {"beat": "B6", "type": "ASK", "spoken": "Just so I have the sequence right — when did you first realize it had not gone out?", "direction": "Read once, verbatim.", "capture": [{"set": "C9", "state": "open"}, {"set": "C5a", "state": "update"}, {"set": "C5b", "state": "open"}]}, {"beat": "B7", "type": "SAY", "spoken": "Thank you. I will look out for it.", "direction": "End the session.", "capture": [{"set": "C1", "state": "final"}, {"set": "C2", "state": "final"}, {"set": "C3a", "state": "final"}, {"set": "C4a", "state": "final"}, {"set": "C5a", "state": "final"}, {"set": "C6a", "state": "final"}, {"set": "C7a", "state": "final"}, {"set": "C8a", "state": "final"}, {"set": "C9", "state": "final"}]}], "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The commitment was the participant''s own"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three in-session performable acts"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "ACT-01 to ACT-03 eligible"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "Two affected parties on the call"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point already passed; knowledge_point at B3"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point at B3"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "Served because the opportunity is genuine and a substantive attributed-to-no-person option exists"}, {"question": "Q-D2-06b", "state": "NOT SERVED", "basis": "The source designates no attribution_support_set item, so the bound question cannot be offered"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "B5 invites a step"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "DIRECT", "basis": "B4 requests a date"}, {"question": "Q-D2-09", "state": "DIRECT", "basis": "knowledge_test_point at B6"}], "material_map": [{"Item": "MD1", "Item text": "that the comparison was not sent", "Where the participant meets it": "The pre-brief", "Quoted text": "You did not send it"}, {"Item": "MD2", "Item text": "that the commitment was made two weeks ago", "Where the participant meets it": "The pre-brief", "Quoted text": "weeks ago, on a"}, {"Item": "MD3", "Item text": "that it is recorded in the participant''s own notes", "Where the participant meets it": "The pre-brief", "Quoted text": "It is in your notes from that call"}, {"Item": "CR1", "Item text": "the commitment was made on a call two weeks ago", "Where the participant meets it": "The pre-brief", "Quoted text": "weeks ago, on a call"}, {"Item": "CR2", "Item text": "it is recorded in the participant''s notes", "Where the participant meets it": "The pre-brief", "Quoted text": "It is in your notes from that call"}, {"Item": "CR3", "Item text": "the comparison was not sent", "Where the participant meets it": "The pre-brief", "Quoted text": "You did not send it"}, {"Item": "CS1", "Item text": "\"by the end of the following week\"", "Where the participant meets it": "The pre-brief", "Quoted text": "by the end of the following week"}], "source_sheet": {"d2_situation_class": "SC-D2-2", "workplace_demand": "A commitment made to a client and not kept, raised by the client in front of the participant''s supervisor.", "relevant_conduct": "What was stated about who held the commitment; whether it was raised before B3 or only after; what the statement contained; the account of why it did not go; whether anything or anyone else was named as cause; the step and its holder; the new date; the answer at B6.", "irrelevant_conduct": "The participant''s workload; the merits of the three tiers; the client organization''s decision process.", "stated_standard": "\"You said you would have it to them by the end of the following week. It is in your notes from that call.\" Exact pre-brief text. THE PARTICIPANT''S OWN NOTE IS THE RECORD.", "stated_standard_source_quote_or_location": "\"You said you would have it to them by the end of the following week. It is in your notes from that call\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Pronunciation only; accommodations recorded.", "unsupported_inferences": "That forgetting indicates unreliability; that an apology is or is not required; anything about the participant''s organization or memory.", "compatibility_class": "S2-SEVEN-BEAT", "item_ownership_state": "Held_by_participant.", "knowledge_point": "B3. UNTIL THE OPERATIONS DIRECTOR RAISES IT, THE SOURCE ESTABLISHES THE PARTICIPANT HAS NOT THOUGHT ABOUT IT. This is the only source in the Stage 2 bank where the knowledge point sits inside the session, and Q-D2-04a A1 is therefore unreachable unless the participant recalls it unprompted at B2.", "impact_point": "The end of the following week, two weeks ago, already passed.", "enquiry_point": "B3", "enquiry_note": null, "knowledge_test_point": "B6", "affected_party": "the client organization''s operations director", "affected_party_note": "The supervisor is a second affected party, present on the call.", "available_actions": [{"id": "ACT1", "text": "state that it was not sent"}, {"id": "ACT2", "text": "commit a date in the session"}, {"id": "ACT3", "text": "state it to the supervisor as well as the client"}], "material_disclosure_items": [{"id": "MD1", "text": "that the comparison was not sent"}, {"id": "MD2", "text": "that the commitment was made two weeks ago"}, {"id": "MD3", "text": "that it is recorded in the participant''s own notes"}], "causal_record_set": [{"id": "CR1", "text": "the commitment was made on a call two weeks ago"}, {"id": "CR2", "text": "it is recorded in the participant''s notes"}, {"id": "CR3", "text": "the comparison was not sent"}], "attribution_support_set": [], "accountable_actor_set": [{"id": "AA1", "text": "the supervisor"}], "constraint_set": [{"id": "CS1", "text": "\"by the end of the following week\""}], "list_note": "Not selectable, planning content only: prepare the comparison. Recorded as explicit none. THE RECORD SUPPORTS NO ATTRIBUTION TO ANOTHER PERSON. Only UNSUPPORTED_ATTRIBUTION is reachable where an attribution is made. Exact text.", "source_note": null, "situation_class_label": "A shortfall the person contributed to, not yet known to the affected party, with its cause on record", "observation_mode_label": "structured_live_session", "min_seconds": 420, "max_seconds": 900}, "source_identifier": "SRC-D2-S2-010", "stage_code": "S2", "source_version_hash": "d6940d63994b7ab61c28ddf3801f28b1b7b8c641b9a286755f1fcb6f1661c593", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S2-010' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S3-001', 'source'::public.t3a_content_family, 'SERVICE RECOVERY AFTER THE OUTAGE', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "SERVICE RECOVERY AFTER THE OUTAGE", "source_digest": "484ccbad9f3fb167d7672ac78498a758c4c9ab0b2d278ec1b2827f90af33b47f", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You hold the client relationship for the client organization. Over the weekend they experienced a system outage during their peak dispatch window. Assignments failed to populate for roughly ninety minutes. Their operations director emailed your vice-president late Sunday night, copying you. Your vice-president forwarded it to you on Monday morning with one line: \"Own this. I want to see your plan before anything goes to the client.\" Your engineering team''s internal thread shows conflicting accounts. The lead engineer says the cause was a third-party rate limit rather than a fault in your own system. A junior engineer posted that warning signs were seen two weeks earlier and were not prioritized. Nothing is confirmed. No incident postmortem has been started. You do not have a confirmed root cause. The client organization''s deadline is Wednesday at 5:00 PM."}], "submission_instructions": "Produce: a response to the operations director; an internal recovery plan for your vice-president stating what is known and what is not known, next actions with timeframes, what you need from engineering and by when; and a short note explaining what you chose to say, what you chose not to say, and how you handled the conflicting internal accounts. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The vice-president''s instruction places it with the participant"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three actions evidenced in the submission"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "Two affected parties addressed in the deliverables"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point passed; knowledge_point Monday"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items. THE STRONGEST CE-D2-05 SOURCE IN THIS BANK, because two of the four are explicitly unverified"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "The opportunity to attribute is genuine"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Only the no-confirmed-cause item is selectable; repeating either engineer''s account resolves to UNSUPPORTED_ATTRIBUTION"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "The recovery plan is a named deliverable"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "NOT SERVED", "basis": "CE-D2-08 not in launch design at Stage 3"}, {"question": "Q-D2-09", "state": "NOT SERVED", "basis": "CE-D2-09 not in launch design at Stage 3"}], "material_map": [{"Item": "MD1", "Item text": "that assignments failed for roughly ninety minutes", "Where the participant meets it": "Pack document D1", "Quoted text": "Assignments failed to populate for roughly ninety minutes"}, {"Item": "MD2", "Item text": "that no root cause is confirmed", "Where the participant meets it": "Pack document D1", "Quoted text": "a confirmed root cause"}, {"Item": "MD3", "Item text": "that no postmortem has been started", "Where the participant meets it": "Pack document D1", "Quoted text": "postmortem has been started"}, {"Item": "MD4", "Item text": "when the client will next hear", "Where the participant meets it": "Pack document D1", "Quoted text": "The client organization''s deadline is Wednesday at 5:00 PM"}, {"Item": "CR1", "Item text": "assignments failed to populate for roughly ninety minutes", "Where the participant meets it": "Pack document D1", "Quoted text": "Assignments failed to populate for roughly ninety minutes"}, {"Item": "CR2", "Item text": "the lead engineer attributes it to a third-party rate limit", "Where the participant meets it": "Pack document D1", "Quoted text": "lead engineer says the cause was a third-party rate limit"}, {"Item": "CR3", "Item text": "a junior engineer''s claim about earlier warning signs is unverified", "Where the participant meets it": "Pack document D1", "Quoted text": "junior engineer posted that warning signs were seen two weeks earlier"}, {"Item": "CR4", "Item text": "no postmortem has been initiated", "Where the participant meets it": "Pack document D1", "Quoted text": "No incident postmortem has been started"}, {"Item": "AS1", "Item text": "no confirmed root cause exists", "Where the participant meets it": "Pack document D1", "Quoted text": "a confirmed root cause"}, {"Item": "CS1", "Item text": "\"Wednesday at 5:00 PM\"", "Where the participant meets it": "Pack document D1", "Quoted text": "Wednesday at 5:00 PM"}, {"Item": "CS2", "Item text": "\"before anything goes to the client\"", "Where the participant meets it": "Pack document D1", "Quoted text": "before anything goes to the client"}], "source_sheet": {"d2_situation_class": "SC-D2-5", "workplace_demand": "Holding a client-facing failure whose cause is not established and sits in another team''s work.", "relevant_conduct": "What the submission states about who holds the recovery; what is stated to the client and what it contains; the account of cause against what the record supports; whether engineering or the third party is named and whether the naming is supported; the steps named and their holders.", "irrelevant_conduct": "The technical merits of either engineering account; writing quality; the client organization''s tone.", "stated_standard": "\"Own this. I want to see your plan before anything goes to the client.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"Own this. I want to see your plan before anything goes to the client\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That either engineering account is true; that the warning signs were ignored; that the participant should or should not repeat the junior engineer''s claim.", "compatibility_class": "S3-ASYNC-SUBMISSION", "item_ownership_state": "Held_by_participant, from the vice-president''s instruction.", "knowledge_point": "Monday 7:15 AM, on receiving the forwarded email.", "impact_point": "Saturday, the dispatch window, already passed.", "enquiry_note": "The vice-president''s instruction.", "affected_party": "the client organization''s operations director", "affected_party_note": "The vice-president is a second affected party.", "available_actions": [{"id": "ACT1", "text": "state what is known and not known in the client response"}, {"id": "ACT2", "text": "name the engineering asks with due times"}, {"id": "ACT3", "text": "initiate the postmortem"}], "material_disclosure_items": [{"id": "MD1", "text": "that assignments failed for roughly ninety minutes"}, {"id": "MD2", "text": "that no root cause is confirmed"}, {"id": "MD3", "text": "that no postmortem has been started"}, {"id": "MD4", "text": "when the client will next hear"}], "causal_record_set": [{"id": "CR1", "text": "assignments failed to populate for roughly ninety minutes"}, {"id": "CR2", "text": "the lead engineer attributes it to a third-party rate limit"}, {"id": "CR3", "text": "a junior engineer''s claim about earlier warning signs is unverified"}, {"id": "CR4", "text": "no postmortem has been initiated"}], "attribution_support_set": [{"id": "AS1", "text": "no confirmed root cause exists"}], "accountable_actor_set": [{"id": "AA1", "text": "the engineering team"}, {"id": "AA2", "text": "the vice-president"}], "constraint_set": [{"id": "CS1", "text": "\"Wednesday at 5:00 PM\""}, {"id": "CS2", "text": "\"before anything goes to the client\""}], "list_note": "The lead engineer''s third-party attribution and the junior engineer''s warning-signs claim are STATEMENTS MADE BY CHARACTERS, not facts created by the source, and neither is selectable.", "source_note": null, "situation_class_label": "A shortfall arising from another person''s work or an inherited state the person now holds", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D2-S3-001", "stage_code": "S3", "source_version_hash": "484ccbad9f3fb167d7672ac78498a758c4c9ab0b2d278ec1b2827f90af33b47f", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S3-001' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S3-002', 'source'::public.t3a_content_family, 'THE MONDAY TRIAGE', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE MONDAY TRIAGE", "source_digest": "38b14025fbee877083691b59966974d832a3a9e50dcf71083abb63901f515cee", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You manage a property portfolio. At 8:00 AM Monday three urgent matters arrive at once. First: the heating and cooling system on floors three to five of the flagship property failed overnight. Two anchor tenants have complained and one has an investor presentation at 2:00 PM today. Those tenants are about thirty-five per cent of that building''s rental revenue. Second: the finance team needs your sign-off on a quarterly maintenance reconciliation, due to the chief financial officer by noon Tuesday. You have not reviewed it. It covers eight months, three of them before you joined, and finance has flagged two line items that do not look right. Third: a tenant at a secondary property has submitted a written complaint about repeated lighting failures, referencing a commitment your predecessor made that the issue would be resolved by the end of February. It is mid-March. The work order opened six weeks ago has no update logged. Your director is traveling and expects a situation update by email before 5:00 PM. You have one junior coordinator who can take one task with clear instructions."}], "submission_instructions": "Produce: a triage plan stating what you address first, second and third with your reasoning, what you delegate and to whom, and your timeline for the next forty-eight hours; a situation update to your director; and a log of what you assumed, what you do not know and what you need to verify. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "Three matters, each requiring a statement of who carries it"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three actions evidenced in the submission"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The director is the addressee of the update"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "In play on this source"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty and supported — the pre-tenure period is a fact of the record"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "ATTRIBUTION TO THE PREDECESSOR IS NOT SELECTABLE and resolves to UNSUPPORTED_ATTRIBUTION"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "The triage plan names steps"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "accountable_actor_set includes the coordinator"}, {"question": "Q-D2-08a", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D2-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "MD1", "Item text": "that the heating failure affects two anchor tenants", "Where the participant meets it": "Pack document D1", "Quoted text": "anchor tenants have complained"}, {"Item": "MD2", "Item text": "that the reconciliation has not been reviewed", "Where the participant meets it": "Pack document D1", "Quoted text": "You have not reviewed it"}, {"Item": "MD3", "Item text": "that two line items are flagged", "Where the participant meets it": "Pack document D1", "Quoted text": "flagged two line items"}, {"Item": "MD4", "Item text": "that one coordinator is available for one task", "Where the participant meets it": "Pack document D1", "Quoted text": "coordinator who can take one task"}, {"Item": "CR1", "Item text": "the heating system failed overnight", "Where the participant meets it": "Pack document D1", "Quoted text": "heating and cooling system on floors three to five of the flagship property failed overnight"}, {"Item": "CR2", "Item text": "the reconciliation covers three months before the participant''s tenure", "Where the participant meets it": "Pack document D1", "Quoted text": "covers eight months, three"}, {"Item": "CR3", "Item text": "finance has flagged two line items", "Where the participant meets it": "Pack document D1", "Quoted text": "finance has flagged two line items"}, {"Item": "AS1", "Item text": "three months of the reconciliation period predate the participant''s tenure", "Where the participant meets it": "Pack document D1", "Quoted text": "months, three of them"}, {"Item": "CS1", "Item text": "\"before 5:00 PM\"", "Where the participant meets it": "Pack document D1", "Quoted text": "before 5:00 PM. You"}, {"Item": "CS2", "Item text": "\"by noon Tuesday\"", "Where the participant meets it": "Pack document D1", "Quoted text": "by noon Tuesday. You"}, {"Item": "CS3", "Item text": "\"one task\"", "Where the participant meets it": "Pack document D1", "Quoted text": "one task with clear"}], "source_sheet": {"d2_situation_class": "SC-D2-6", "workplace_demand": "Holding more than can be carried and stating which parts will not be.", "relevant_conduct": "What the submission states about who holds each matter; what is stated to the director and what it contains; the account of the reconciliation position; the steps named and their holders.", "irrelevant_conduct": "The correctness of the triage order; the heating fault; the predecessor''s commitment or conduct.", "stated_standard": "\"an update by email before 5:00 PM\"; \"due to the chief financial officer by noon Tuesday.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"due to the chief financial officer by noon Tuesday\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That any particular ordering is correct; that delegating or not delegating indicates anything; anything about the predecessor.", "compatibility_class": "S3-ASYNC-SUBMISSION", "item_ownership_state": "Held_by_participant.", "knowledge_point": "8:00 AM Monday, when all three arrive.", "impact_point": "2:00 PM today for the tenant presentation; noon Tuesday for the reconciliation.", "enquiry_note": "The director''s standing expectation of a 5:00 PM update.", "affected_party": "the director", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state the heating position and the tenant impact"}, {"id": "ACT2", "text": "state that the reconciliation has not been reviewed and name a time"}, {"id": "ACT3", "text": "assign one task to the junior coordinator with stated instructions"}], "material_disclosure_items": [{"id": "MD1", "text": "that the heating failure affects two anchor tenants"}, {"id": "MD2", "text": "that the reconciliation has not been reviewed"}, {"id": "MD3", "text": "that two line items are flagged"}, {"id": "MD4", "text": "that one coordinator is available for one task"}], "causal_record_set": [{"id": "CR1", "text": "the heating system failed overnight"}, {"id": "CR2", "text": "the reconciliation covers three months before the participant''s tenure"}, {"id": "CR3", "text": "finance has flagged two line items"}], "attribution_support_set": [{"id": "AS1", "text": "three months of the reconciliation period predate the participant''s tenure"}], "accountable_actor_set": [{"id": "AA1", "text": "the junior coordinator"}, {"id": "AA2", "text": "the director"}, {"id": "AA3", "text": "the finance team"}], "constraint_set": [{"id": "CS1", "text": "\"before 5:00 PM\""}, {"id": "CS2", "text": "\"by noon Tuesday\""}, {"id": "CS3", "text": "\"one task\""}], "list_note": null, "source_note": "The lighting complaint references a commitment made by a person who has left. Handling a commitment made by a predecessor is one of the two conduct elements held back from the D2 launch construct at Section 3.4. It remains in the brief as SITUATION CONTEXT because removing it would change the triage problem, but NO QUESTION IS SERVED ON IT and no determination, statement or clause may be composed from it. The mentor records determinations from the first two strands and the triage decision as a whole.", "situation_class_label": "A matter beyond the person''s authority, knowledge or resources, with time short", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D2-S3-002", "stage_code": "S3", "source_version_hash": "38b14025fbee877083691b59966974d832a3a9e50dcf71083abb63901f515cee", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S3-002' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S3-003', 'source'::public.t3a_content_family, 'THE ANALYSIS AT FORTY PER CENT', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE ANALYSIS AT FORTY PER CENT", "source_digest": "b3cbd0ddda33a67f7423700f17860686bf1da82d88dd75981c04521c9c99602d", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You coordinate an engagement for the client organization. The subject-matter specialist responsible for the regulatory gap analysis — due to the client this Friday — tells you on Monday afternoon that she is behind. It is about forty per cent complete and she cannot finish it by Friday without deprioritising another engagement led by a different partner. You have no authority over her time. The engagement partner is traveling and unreachable until Wednesday evening. His voice message says: \"Handle whatever comes up. I trust your judgment. Loop me in Wednesday night if needed.\" The tracker shows the analysis is on the critical path. If it slips, the client organization''s compliance review next Tuesday will not have its input document. The client has not been told. Firm policy is that client-facing deadline changes are communicated proactively, not discovered by the client. There is no budget for additional specialist hours."}], "submission_instructions": "Produce: a briefing to the client organization''s sponsor about the delivery risk and a proposed revised timeline or interim deliverable; a preparation note for the Wednesday call with the partner stating what you have already done, what decisions you need from him and what options you have identified; and a summary of the risks, dependencies and constraints. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "Ownership is contested between the engagement and the deliverable"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three actions evidenced in the submission"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "Two affected parties addressed"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point is Friday, in the future"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty and supported"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "The specialist is NEVER NAMED in a rendered statement"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "The proposal is a named deliverable"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D2-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "MD1", "Item text": "that the analysis is about forty per cent complete", "Where the participant meets it": "Pack document D1", "Quoted text": "forty per cent complete"}, {"Item": "MD2", "Item text": "that it will not be ready by Friday", "Where the participant meets it": "Pack document D1", "Quoted text": "she cannot finish it by Friday"}, {"Item": "MD3", "Item text": "that the compliance review depends on it", "Where the participant meets it": "Pack document D1", "Quoted text": "compliance review next Tuesday"}, {"Item": "CR1", "Item text": "the analysis is about forty per cent complete", "Where the participant meets it": "Pack document D1", "Quoted text": "forty per cent complete"}, {"Item": "CR2", "Item text": "the specialist is committed to another engagement", "Where the participant meets it": "Pack document D1", "Quoted text": "another engagement led by"}, {"Item": "CR3", "Item text": "the participant has no authority over her time", "Where the participant meets it": "Pack document D1", "Quoted text": "authority over her time"}, {"Item": "CR4", "Item text": "there is no budget for additional specialist hours", "Where the participant meets it": "Pack document D1", "Quoted text": "budget for additional specialist hours"}, {"Item": "AS1", "Item text": "the specialist''s time is committed to an engagement led by a different partner", "Where the participant meets it": "Pack document D1", "Quoted text": "engagement led by a different partner"}, {"Item": "AS2", "Item text": "the participant has no authority to redirect her", "Where the participant meets it": "Pack document D1", "Quoted text": "You have no authority over her time"}, {"Item": "CS1", "Item text": "\"this Friday\"", "Where the participant meets it": "Pack document D1", "Quoted text": "this Friday — tells"}, {"Item": "CS2", "Item text": "\"next Tuesday\"", "Where the participant meets it": "Pack document D1", "Quoted text": "the client organization''s compliance review next Tuesday"}, {"Item": "CS3", "Item text": "\"no budget for additional specialist hours\"", "Where the participant meets it": "Pack document D1", "Quoted text": "no budget for additional specialist hours"}], "source_sheet": {"d2_situation_class": "SC-D2-5", "workplace_demand": "Holding a client deadline whose delivery depends on a person the participant cannot direct.", "relevant_conduct": "What the submission states about who holds the delivery risk; whether the client is told, when and what is stated; the account of the position; whether the specialist or the partner is named and whether the naming is supported; the steps named and their holders.", "irrelevant_conduct": "The specialist''s workload or competence; the regulatory content; the partner''s absence.", "stated_standard": "\"client-facing deadline changes are communicated proactively, not discovered by the client.\" Exact brief text. THIS IS THE CLEAREST EXPLICIT STANDARD IN THE STAGE 3 BANK.", "stated_standard_source_quote_or_location": "\"client-facing deadline changes are communicated proactively, not discovered by the client\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That the specialist failed; that waiting for the partner would be wrong; that telling the client early is bravery.", "compatibility_class": "S3-ASYNC-SUBMISSION", "item_ownership_state": "Contested. The analysis is the specialist''s; the engagement and the client relationship are the participant''s.", "knowledge_point": "Monday afternoon, when the specialist tells the participant.", "impact_point": "Friday, the client delivery date, and the following Tuesday review.", "enquiry_note": "None. Nobody asks.", "affected_party": "the client organization''s sponsor", "affected_party_note": "The partner is a second affected party.", "available_actions": [{"id": "ACT1", "text": "state the delivery risk to the client sponsor"}, {"id": "ACT2", "text": "propose a revised timeline or interim deliverable"}, {"id": "ACT3", "text": "state what decisions the partner must make"}], "material_disclosure_items": [{"id": "MD1", "text": "that the analysis is about forty per cent complete"}, {"id": "MD2", "text": "that it will not be ready by Friday"}, {"id": "MD3", "text": "that the compliance review depends on it"}], "causal_record_set": [{"id": "CR1", "text": "the analysis is about forty per cent complete"}, {"id": "CR2", "text": "the specialist is committed to another engagement"}, {"id": "CR3", "text": "the participant has no authority over her time"}, {"id": "CR4", "text": "there is no budget for additional specialist hours"}], "attribution_support_set": [{"id": "AS1", "text": "the specialist''s time is committed to an engagement led by a different partner"}, {"id": "AS2", "text": "the participant has no authority to redirect her"}], "accountable_actor_set": [{"id": "AA1", "text": "the engagement partner"}, {"id": "AA2", "text": "the specialist"}], "constraint_set": [{"id": "CS1", "text": "\"this Friday\""}, {"id": "CS2", "text": "\"next Tuesday\""}, {"id": "CS3", "text": "\"no budget for additional specialist hours\""}], "list_note": null, "source_note": null, "situation_class_label": "A shortfall arising from another person''s work or an inherited state the person now holds", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D2-S3-003", "stage_code": "S3", "source_version_hash": "b3cbd0ddda33a67f7423700f17860686bf1da82d88dd75981c04521c9c99602d", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S3-003' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S3-005', 'source'::public.t3a_content_family, 'THE BATCH WITH THE WRONG LABEL', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE BATCH WITH THE WRONG LABEL", "source_digest": "f081eb61d051fb609cd05556956f5035a0f11bbe167b1ed3e89835d0f19bdb80", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You hold quality responsibility on a production site. A line operator has flagged that a batch of twelve hundred units was packaged with labels showing the wrong dosage instruction. The batch has already passed visual inspection. You investigate. The wrong label template was loaded at the start of the shift. The line lead signed off the pre-run check without catching it. The inspector reviewed a sample and also missed it. The template was left accessible in the system after a product change three months ago and was never archived. The product is safe at either dosage, but distributing it with an incorrect instruction is a compliance event. The batch has not left the facility and can be held if you act before 4:00 PM. The shipping truck is scheduled for 4:00 PM. Your director is in a board meeting until 3:00 PM and has asked not to be disturbed except for regulatory-level issues. Site procedure requires a written investigation within five business days and a corrective action plan within ten."}], "submission_instructions": "Produce: a corrective action outline covering containment, root cause hypothesis, short-term measures and preventive actions; a factual incident summary for your director; and a notification to the production and packaging team explaining the hold and what is required. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The containment decision sits with the participant"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "FOUR actions evidenced in the submission — the richest CE-D2-02 source in the Stage 3 bank"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The director is the addressee of the incident summary"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point 4:00 PM is in the future"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items, THREE OF WHICH INVOLVE OTHER PEOPLE"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "The opportunity to attribute is genuine and substantial"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Only the unarchived template is selectable. NAMING THE LINE LEAD OR THE INSPECTOR resolves to UNSUPPORTED_ATTRIBUTION, because the record states they did not catch it and does not state that they caused it"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "The corrective action outline is a named deliverable"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D2-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "MD1", "Item text": "that twelve hundred units carry the wrong dosage instruction", "Where the participant meets it": "Pack document D1", "Quoted text": "twelve hundred units was packaged with labels showing the wrong dosage instruction"}, {"Item": "MD2", "Item text": "that it is a compliance event", "Where the participant meets it": "Pack document D1", "Quoted text": "is a compliance event"}, {"Item": "MD3", "Item text": "that the batch can be held before 4:00 PM", "Where the participant meets it": "Pack document D1", "Quoted text": "batch has not left the facility and can be held"}, {"Item": "MD4", "Item text": "that three checks did not catch it", "Where the participant meets it": "Pack document D1", "Quoted text": "check without catching it"}, {"Item": "CR1", "Item text": "the wrong template was loaded at the start of the shift", "Where the participant meets it": "Pack document D1", "Quoted text": "wrong label template was loaded at the start of the shift"}, {"Item": "CR2", "Item text": "the pre-run check was signed off without catching it", "Where the participant meets it": "Pack document D1", "Quoted text": "signed off the pre-run check without catching"}, {"Item": "CR3", "Item text": "the sample inspection missed it", "Where the participant meets it": "Pack document D1", "Quoted text": "sample and also missed"}, {"Item": "CR4", "Item text": "the obsolete template was never archived after the product change", "Where the participant meets it": "Pack document D1", "Quoted text": "template was left accessible in the system after a product change three months ago and was never archived"}, {"Item": "AS1", "Item text": "the obsolete template remained accessible in the system after the product change", "Where the participant meets it": "Pack document D1", "Quoted text": "template was left accessible in the system after a product change"}, {"Item": "CS1", "Item text": "\"before 4:00 PM\"", "Where the participant meets it": "Pack document D1", "Quoted text": "before 4:00 PM. The"}, {"Item": "CS2", "Item text": "\"within five business days\"", "Where the participant meets it": "Pack document D1", "Quoted text": "within five business days"}, {"Item": "CS3", "Item text": "\"within ten business days\"", "Where the participant meets it": "Pack document D1", "Quoted text": "within five business days and a corrective action plan within ten"}], "source_sheet": {"d2_situation_class": "SC-D2-2", "workplace_demand": "Holding a compliance failure under a physical deadline with the decision-maker unavailable.", "relevant_conduct": "What the submission states about who holds the containment decision; whether the director is told, when, and what is stated; the account of cause against the four recorded items; whether the line lead or the inspector is named; the steps named and their holders.", "irrelevant_conduct": "The pharmacology; the line lead''s record; whether the director should have been interrupted.", "stated_standard": "\"a written investigation within five business days and a corrective action plan within ten\"; \"held if you act before 4:00 PM.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"a written investigation within five business days and a corrective action plan within ten\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That the line lead or the inspector was negligent; that interrupting the board meeting was required or forbidden; anything about decisiveness.", "compatibility_class": "S3-ASYNC-SUBMISSION", "item_ownership_state": "Held_by_participant.", "knowledge_point": "When the line operator flagged it.", "impact_point": "4:00 PM, when the truck is scheduled.", "enquiry_note": "None. The director has asked not to be disturbed.", "affected_party": "the director", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "hold the batch"}, {"id": "ACT2", "text": "state the position to the director before 3:00 PM"}, {"id": "ACT3", "text": "open the written investigation"}, {"id": "ACT4", "text": "archive the obsolete template"}], "material_disclosure_items": [{"id": "MD1", "text": "that twelve hundred units carry the wrong dosage instruction"}, {"id": "MD2", "text": "that it is a compliance event"}, {"id": "MD3", "text": "that the batch can be held before 4:00 PM"}, {"id": "MD4", "text": "that three checks did not catch it"}], "causal_record_set": [{"id": "CR1", "text": "the wrong template was loaded at the start of the shift"}, {"id": "CR2", "text": "the pre-run check was signed off without catching it"}, {"id": "CR3", "text": "the sample inspection missed it"}, {"id": "CR4", "text": "the obsolete template was never archived after the product change"}], "attribution_support_set": [{"id": "AS1", "text": "the obsolete template remained accessible in the system after the product change"}], "accountable_actor_set": [{"id": "AA1", "text": "the director"}, {"id": "AA2", "text": "the line lead"}, {"id": "AA3", "text": "the inspector"}], "constraint_set": [{"id": "CS1", "text": "\"before 4:00 PM\""}, {"id": "CS2", "text": "\"within five business days\""}, {"id": "CS3", "text": "\"within ten business days\""}], "list_note": null, "source_note": null, "situation_class_label": "A shortfall the person contributed to, not yet known to the affected party, with its cause on record", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D2-S3-005", "stage_code": "S3", "source_version_hash": "f081eb61d051fb609cd05556956f5035a0f11bbe167b1ed3e89835d0f19bdb80", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S3-005' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S3-006', 'source'::public.t3a_content_family, 'THE BRIEF WITH NO DETAIL', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE BRIEF WITH NO DETAIL", "source_digest": "26fe0837d3cb03c9fe8fed36e52fa27629e4f1395ba2e9a01123349c17d7fb80", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You have been asked to lead the initial findings presentation for the client organization. The instruction arrived by email at 4:30 PM Friday: \"Take the lead on pulling together the initial findings deck. Use the discovery data. Client meeting is Thursday at 10 AM. Make it sharp. I''ll review Wednesday afternoon.\" No further detail was given. The discovery package holds six months of complaint volume data, three interview transcripts, a process flow diagram, and an unfinished benchmarking comparison started by a junior analyst who is on leave until Wednesday and cannot be reached. There are three past examples of initial findings presentations on the shared drive. Each has a different structure, depth and level of analysis. There is no template. The client sponsor has previously asked for concrete numbers rather than generalities. The known bottleneck in their process was identified in the interviews but never quantified. Wednesday afternoon is your only checkpoint. This is your first client-facing deliverable here."}], "submission_instructions": "Produce: a note stating how you interpreted the brief, the structure you plan to use, the data you will prioritize and the decisions you need; an outline of the presentation with the key findings and how you will handle the incomplete benchmarking; and a register of the assumptions you are making and what you would verify with more time. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The deliverable is assigned; its scope is not"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three actions evidenced in the submission"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The requester is the addressee of the interpretation note"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point Thursday, in the future"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point is the Wednesday review, so both values reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set non-empty"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty and supported — the brief''s silence is a fact of the record"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "The requester is NEVER NAMED in a rendered statement"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "The structure proposal is a named deliverable"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D2-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "MD1", "Item text": "that the brief specified no structure or depth", "Where the participant meets it": "Pack document D1", "Quoted text": "structure, depth and level"}, {"Item": "MD2", "Item text": "that the benchmarking comparison is incomplete", "Where the participant meets it": "Pack document D1", "Quoted text": "benchmarking comparison started by"}, {"Item": "MD3", "Item text": "that the analyst is unreachable until Wednesday", "Where the participant meets it": "Pack document D1", "Quoted text": "analyst who is on leave until Wednesday"}, {"Item": "CR1", "Item text": "the instruction specified no structure, depth or content", "Where the participant meets it": "Pack document D1", "Quoted text": "structure, depth and level"}, {"Item": "CR2", "Item text": "there is no template and three inconsistent past examples", "Where the participant meets it": "Pack document D1", "Quoted text": "three past examples of"}, {"Item": "CR3", "Item text": "the benchmarking comparison is unfinished and its author is unreachable", "Where the participant meets it": "Pack document D1", "Quoted text": "unfinished benchmarking comparison started"}, {"Item": "AS1", "Item text": "the instruction specified no structure, depth or content", "Where the participant meets it": "Pack document D1", "Quoted text": "structure, depth and level"}, {"Item": "AS2", "Item text": "the junior analyst is on leave and unreachable", "Where the participant meets it": "Pack document D1", "Quoted text": "junior analyst who is on leave"}, {"Item": "CS1", "Item text": "\"Thursday at 10 AM\"", "Where the participant meets it": "Pack document D1", "Quoted text": "Thursday at 10 AM"}, {"Item": "CS2", "Item text": "\"Wednesday afternoon\"", "Where the participant meets it": "Pack document D1", "Quoted text": "Wednesday afternoon.\" No further"}], "source_sheet": {"d2_situation_class": "SC-D2-6", "workplace_demand": "Holding a deliverable whose scope was never specified.", "relevant_conduct": "What the submission states about who holds the scope decision; what is stated back to the requester and what it contains; the account of what the brief did and did not specify; whether the requester or the absent analyst is named; the steps named and their holders.", "irrelevant_conduct": "The quality of the proposed structure; the analytical findings themselves; whether the brief was reasonable.", "stated_standard": "\"Client meeting is Thursday at 10 AM\"; \"I''ll review Wednesday afternoon.\" Exact brief text. NOTHING ELSE IN THE SOURCE ESTABLISHES A REQUIREMENT, and the absence is the situation.", "stated_standard_source_quote_or_location": "\"Client meeting is Thursday at 10 AM\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That the brief should have been clearer; that asking for clarification is weakness or strength; anything about confidence.", "compatibility_class": "S3-ASYNC-SUBMISSION", "item_ownership_state": "Held_by_participant, scope unspecified.", "knowledge_point": "4:30 PM Friday, on receiving the instruction.", "impact_point": "Thursday at 10 AM, the client meeting.", "enquiry_note": "The Wednesday afternoon review.", "affected_party": "the requester", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state the interpretation of the brief before building"}, {"id": "ACT2", "text": "name the decisions required from the requester"}, {"id": "ACT3", "text": "state how the incomplete benchmarking will be handled"}], "material_disclosure_items": [{"id": "MD1", "text": "that the brief specified no structure or depth"}, {"id": "MD2", "text": "that the benchmarking comparison is incomplete"}, {"id": "MD3", "text": "that the analyst is unreachable until Wednesday"}], "causal_record_set": [{"id": "CR1", "text": "the instruction specified no structure, depth or content"}, {"id": "CR2", "text": "there is no template and three inconsistent past examples"}, {"id": "CR3", "text": "the benchmarking comparison is unfinished and its author is unreachable"}], "attribution_support_set": [{"id": "AS1", "text": "the instruction specified no structure, depth or content"}, {"id": "AS2", "text": "the junior analyst is on leave and unreachable"}], "accountable_actor_set": [{"id": "AA1", "text": "the requester"}, {"id": "AA2", "text": "the junior analyst"}], "constraint_set": [{"id": "CS1", "text": "\"Thursday at 10 AM\""}, {"id": "CS2", "text": "\"Wednesday afternoon\""}], "list_note": null, "source_note": null, "situation_class_label": "A matter beyond the person''s authority, knowledge or resources, with time short", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D2-S3-006", "stage_code": "S3", "source_version_hash": "26fe0837d3cb03c9fe8fed36e52fa27629e4f1395ba2e9a01123349c17d7fb80", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S3-006' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S3-007', 'source'::public.t3a_content_family, 'THE PATCH AND THE FIXED DATE', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE PATCH AND THE FIXED DATE", "source_digest": "017c0a985b046dabc5f1ff8a885b2e301f262ebda43a0bca43f5cee5e2149bcf", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You are running a system rollout across a property group. On Monday the vendor tells you a security patch must be applied to all six live properties before any new go-lives proceed. Each patch needs four hours of downtime and the vendor supports only two at a time. On Tuesday your director tells you the chief executive has committed the Friday go-live date to the ownership group: \"Moving the date is not an option.\" The general manager of the highest-revenue property in Friday''s wave calls you: occupancy is ninety-four per cent this weekend, and any disruption to the front desk during check-in will be held against you personally. What you know: patching can run overnight but needs on-site support; your three-person team can cover two properties a night, so six properties take three nights and leave Thursday for testing; the vendor offers remote support at an additional twenty-five hundred dollars per property, compressing it to two nights; the patch does not affect booking functionality, only a secondary encryption module; your team lead says it can be done but with zero buffer."}], "submission_instructions": "Produce: an implementation memo to your director covering the situation, the patching timeline, the resource options and costs, and your recommended approach; a note explaining the competing constraints and how you propose to resolve them, stating what you are accepting as risk and what you are mitigating; and a day-by-day timeline with owners and single points of failure flagged. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The rollout sits with the participant"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Four actions evidenced in the submission"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The director is the addressee of the memo"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point Friday, in the future"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "enquiry_point Tuesday, both values reachable"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "TWO SUPPORTED NON-SELF ATTRIBUTIONS EXIST, which is unusual and makes this the source where a supported shared attribution is most likely"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "A recommendation is a required deliverable"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "accountable_actor_set has four entries"}, {"question": "Q-D2-08a", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D2-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "MD1", "Item text": "that the patch is a precondition of any go-live", "Where the participant meets it": "Pack document D1", "Quoted text": "patch must be applied to all six live properties before any"}, {"Item": "MD2", "Item text": "that internal capacity gives zero buffer", "Where the participant meets it": "Pack document D1", "Quoted text": "but with zero buffer"}, {"Item": "MD3", "Item text": "that vendor support costs twenty-five hundred dollars per property", "Where the participant meets it": "Pack document D1", "Quoted text": "properties take three nights and leave Thursday for testing; the vendor offers remote support at an additional twenty-five hundred dollars per property"}, {"Item": "MD4", "Item text": "that the patch does not affect front-desk operations", "Where the participant meets it": "Pack document D1", "Quoted text": "vendor offers remote support at an additional twenty-five hundred dollars per property, compressing it to two nights; the patch does not affect"}, {"Item": "CR1", "Item text": "the vendor requires the patch before new go-lives", "Where the participant meets it": "Pack document D1", "Quoted text": "vendor tells you a security patch must be applied to all six live properties before any new"}, {"Item": "CR2", "Item text": "the team can cover two properties a night", "Where the participant meets it": "Pack document D1", "Quoted text": "can run overnight but needs on-site support; your three-person team can cover two properties a night, so six properties take three nights"}, {"Item": "CR3", "Item text": "six properties therefore take three nights", "Where the participant meets it": "Pack document D1", "Quoted text": "properties a night, so six properties take three nights and leave Thursday for testing; the vendor offers remote support at an additional"}, {"Item": "CR4", "Item text": "the chief executive committed the Friday date", "Where the participant meets it": "Pack document D1", "Quoted text": "chief executive has committed the Friday go-live date to the ownership group: \"Moving the date"}, {"Item": "AS1", "Item text": "the vendor introduced the patch requirement on Monday", "Where the participant meets it": "Pack document D1", "Quoted text": "Monday the vendor tells you a security patch"}, {"Item": "AS2", "Item text": "the date was committed by the chief executive", "Where the participant meets it": "Pack document D1", "Quoted text": "chief executive has committed the Friday go-live date to the ownership group: \"Moving the date"}, {"Item": "CS1", "Item text": "\"Friday\"", "Where the participant meets it": "Pack document D1", "Quoted text": "Friday go-live date to"}, {"Item": "CS2", "Item text": "\"four hours of downtime per property\"", "Where the participant meets it": "Pack document D1", "Quoted text": "four hours of downtime"}, {"Item": "CS3", "Item text": "\"two patches simultaneously\"", "Where the participant meets it": "Pack document D1", "Quoted text": "the vendor supports only two at a time"}, {"Item": "CS4", "Item text": "\"twenty-five hundred dollars per property\"", "Where the participant meets it": "Pack document D1", "Quoted text": "twenty-five hundred dollars per property"}], "source_sheet": {"d2_situation_class": "SC-D2-6", "workplace_demand": "Holding a fixed commitment whose delivery depends on capacity the participant does not have.", "relevant_conduct": "What the submission states about who holds the go-live risk; what is stated to the director and what it contains; the account of the constraints; whether the vendor, the team or the chief executive is named; the steps named and their holders; what risk is stated as accepted.", "irrelevant_conduct": "The technical merits of the patch; whether the date should have been committed; the general manager''s tone.", "stated_standard": "\"Moving the date is not an option\"; the patch \"must be applied to all six live properties before any new go-lives can proceed.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"Moving the date is not an option\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": "That paying for vendor support is right or wrong; that the participant should push back on the date; anything about risk appetite as a trait.", "compatibility_class": "S3-ASYNC-SUBMISSION", "item_ownership_state": "Held_by_participant.", "knowledge_point": "Monday, when the vendor states the patch requirement.", "impact_point": "Friday, the committed go-live.", "enquiry_note": "Tuesday, the director''s statement about the date.", "affected_party": "the director", "affected_party_note": null, "available_actions": [{"id": "ACT1", "text": "state the patch constraint and its timeline effect"}, {"id": "ACT2", "text": "state the zero-buffer position from the team lead"}, {"id": "ACT3", "text": "recommend a path with its cost"}, {"id": "ACT4", "text": "state the accepted risk explicitly"}], "material_disclosure_items": [{"id": "MD1", "text": "that the patch is a precondition of any go-live"}, {"id": "MD2", "text": "that internal capacity gives zero buffer"}, {"id": "MD3", "text": "that vendor support costs twenty-five hundred dollars per property"}, {"id": "MD4", "text": "that the patch does not affect front-desk operations"}], "causal_record_set": [{"id": "CR1", "text": "the vendor requires the patch before new go-lives"}, {"id": "CR2", "text": "the team can cover two properties a night"}, {"id": "CR3", "text": "six properties therefore take three nights"}, {"id": "CR4", "text": "the chief executive committed the Friday date"}], "attribution_support_set": [{"id": "AS1", "text": "the vendor introduced the patch requirement on Monday"}, {"id": "AS2", "text": "the date was committed by the chief executive"}], "accountable_actor_set": [{"id": "AA1", "text": "the director"}, {"id": "AA2", "text": "the information technology team"}, {"id": "AA3", "text": "the vendor"}], "constraint_set": [{"id": "CS1", 