  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S3-008', 'source'::public.t3a_content_family, 'THE REDUCED GRANT', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE REDUCED GRANT", "source_digest": "6af5b4cd9b9a64498869101f01d32f7c8205e48fb16421c3fab2fe8b10eabc21", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You hold program responsibility at a community organization. On Monday the executive director tells you a provincial grant — funding thirty per cent of the employment pathways program and fifteen per cent of the youth integration program — has been cut by forty per cent from next quarter. The reduction is confirmed and cannot be reversed. The employment pathways manager says that without the full grant she must either cancel the spring workshop series, which serves sixty clients, or reduce her staff from four to two and a half full-time equivalents. She needs a decision by Friday. The youth integration coordinator writes that the afterschool mentoring program, serving thirty-five young people, will lose its paid supervisor position, and without a supervisor the volunteer facilitators cannot operate. What you know: the reserve fund holds about forty thousand dollars, board-earmarked for emergencies and requiring board approval with written justification; the workshop series has a seventy-eight per cent completion rate and is a reporting metric under the municipal funding agreement; the mentoring program is a signature program for donor communications; an employer partner has informally offered to co-fund a placement stream if you can match staff time, but nothing is formalized; the settlement support program is separately funded and unaffected. The executive director has said: \"I trust your analysis. Bring me a recommendation — not just a problem.\""}], "submission_instructions": "Produce: an allocation plan stating what you would cut, preserve and restructure across the two affected programs and why, addressing staffing, scope and client impact; a justification memo for the executive director with the rationale, the trade-offs and any alternative measures; and a summary of who is affected and how you would communicate the change to each group. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "The allocation decision is placed with the participant"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three actions evidenced in the submission"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "The executive director is the addressee; the communication summary addresses the others"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point next quarter, in the future"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "The opportunity to attribute is genuine"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "THE ONLY SUPPORTED ATTRIBUTION IS TO AN ENTITY, not a person. This is the source that proves an entity attribution renders without naming anybody"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "A recommendation is a required deliverable"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": 