formally offered"}, {"Item": "AS1", "Item text": "the funder reduced the grant", "Where the participant meets it": "Pack document D1", "Quoted text": "has been cut by forty per cent from next quarter"}, {"Item": "CS1", "Item text": "\"by Friday\"", "Where the participant meets it": "Pack document D1", "Quoted text": "by Friday. The youth"}, {"Item": "CS2", "Item text": "\"next quarter\"", "Where the participant meets it": "Pack document D1", "Quoted text": "next quarter. The reduction"}, {"Item": "CS3", "Item text": "\"requires board approval\"", "Where the participant meets it": "Pack document D1", "Quoted text": "requiring board approval with"}, {"Item": "CS4", "Item text": "\"nothing is formalized\"", "Where the participant meets it": "Pack document D1", "Quoted text": "but nothing is formalized"}], "source_sheet": {"d2_situation_class": "SC-D2-6", "workplace_demand": "Holding a decision whose consequences fall on people the participant cannot compensate.", "relevant_conduct": "What the submission states about who holds the allocation decision; what is stated to the executive director and to each affected group; the account of the constraint; whether the funder or anyone else is named; the steps named and their holders.", "irrelevant_conduct": "Whether the allocation chosen is the right one; the merits of either program; the funder''s reasoning.", "stated_standard": "\"Bring me a recommendation — not just a problem\"; \"a decision by Friday.\" Exact brief text.", "stated_standard_source_quote_or_location": "\"Bring me a recommendation — not just a problem\"", "cross_context_map": null, "serving_eligible": false, "recurrence_eligible": true, "replacement_required": false, "name_clearance_status": "CLEARED", "name_clearance_basis": "Controlled role and entity labels only; no real person or organization is named.", "sensitivity_flag": null, "permitted_administration_variance": "Extended time and assistive software permitted and recorded.", "unsupported_inferences": 