ague.", "source_note": null, "situation_class_label": "A matter beyond the person''s authority, knowledge or resources, with time short", "observation_mode_label": "work_sample", "ai_use": "AI_USE_DECLARATION_REQUIRED", "submission_window_days": 3}, "source_identifier": "SRC-D2-S3-008", "stage_code": "S3", "source_version_hash": "6af5b4cd9b9a64498869101f01d32f7c8205e48fb16421c3fab2fe8b10eabc21", "serving_eligible": false, "verbatim": ""}'::jsonb from public.t3a_content_object where identifier = 'SRC-D2-S3-008' and family = 'source'::public.t3a_content_family;
  insert into public.t3a_content_object(identifier, family, title, dimension_id, current_operational_state) values ('SRC-D2-S3-009', 'source'::public.t3a_content_family, 'THE FEATURE THE CUSTOMERS WERE PROMISED', 'D2', 'not_loaded'::public.t3a_operational_state);
  insert into public.t3a_d1_content_version(content_object_id, version_no, approval_status, operational_state, body) select content_object_id, 'v2.1', 'drafting', 'not_loaded'::public.t3a_operational_state, '{"stage": 3, "title": "THE FEATURE THE CUSTOMERS WERE PROMISED", "source_digest": "e5359a029dbe0f43f32d7a63052fc73c8b1ac995cd1b5e37478851157413d15c", "brief_summary": "The participant reads the brief in the pack and submits the work the submission instructions name.", "participant_pack": [{"document": "D1", "title": "The brief", "text": "You hold the product decision. The customer success lead has escalated a request: three of the largest customers are threatening to leave unless a payroll integration is delivered within six weeks. She has already told those customers the feature is on the roadmap. She made that commitment without consulting engineering or product, and acknowledges it was premature. The engineering lead pushes back: the integration cannot be built in six weeks without pulling engineers off a performance upgrade that is sixty per cent complete and affects all one hundred and forty customers, against three for the payroll feature. What you know: the three customers are about twelve per cent of recurring revenue; the performance work addresses latency that generated twenty-two support tickets last month; a partial integration — export only, no real-time sync — could be built in three weeks by one engineer without touching the performance work, and would address the core need without fully meeting the request; the partial option has not been discussed with the customers or with engineering. Your vice-president has told you: \"Own this. Bring me a recommendation by Thursday. I don''t want to referee — I want you to align the teams.\""}], "submission_instructions": "Produce: an alignment memo to both leads proposing a resolution; a decision recommendation for your vice-president covering the options, their risks and benefits, and your recommended path; and a draft summary for the alignment meeting with the agenda and the decision criteria you propose. The work is submitted within 3 days.", "question_applicability": [{"question": "Q-D2-01", "state": "DIRECT", "basis": "item_ownership_state is unassigned as to the commitment. THE STRONGEST CE-D2-01 SOURCE IN THE STAGE 3 BANK"}, {"question": "Q-D2-02", "state": "DIRECT", "basis": "Three actions evidenced in the submission"}, {"question": "Q-D2-02b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-03a", "state": "DIRECT", "basis": "Three affected parties addressed across the deliverables"}, {"question": "Q-D2-03b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-04a", "state": "DIRECT", "basis": "impact_point six weeks, in the future"}, {"question": "Q-D2-04b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-05a", "state": "DIRECT", "basis": "causal_record_set has four items"}, {"question": "Q-D2-05b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-06a", "state": "DIRECT", "basis": "attribution_support_set non-empty and SUPPORTED BY THE LEAD''S OWN ACKNOWLEDGMENT"}, {"question": "Q-D2-06b", "state": "CONDITIONAL", "basis": "THE CUSTOMER SUCCESS LEAD IS NEVER NAMED in a rendered statement"}, {"question": "Q-D2-07a", "state": "DIRECT", "basis": "A recommendation is a required deliverable"}, {"question": "Q-D2-07b", "state": "CONDITIONAL", "basis": "Served once its parent records a serving answer"}, {"question": "Q-D2-08a", "state": "NOT SERVED", "basis": "Stage 3 launch design"}, {"question": "Q-D2-09", "state": "NOT SERVED", "basis": "Stage 3 launch design"}], "material_map": [{"Item": "MD1", "Item text": "that the commitment was made without consulting engineering or product", "Where the participant meets it": "Pack document D1", "Quoted text": 